window.QBANK={"1": [{"e": "IPAT 핵심", "i": "IPAT-4-1-1o", "t": "지식재산권의 사업화 방법에는 스타트업 설립, 기존 법인 매수, 합작투자 기업 설립, 라이선싱, 지식재산권 판매, 담보 대출, 특허 소송 등 적극적 권리행사를 통한 수익화가 있다.", "ox": "O", "c": "A", "tp": "사업화 방법의 종류"}, {"e": "IPAT 핵심", "i": "IPAT-4-1-2o", "t": "사업화 유형은 리스크와 수익이 함께 커지는 관계로, IP 매각이 가장 낮고 전략적 제휴, 라이선싱, 합작투자, 기업 매수를 거쳐 벤처 창업이 가장 높다.", "ox": "O", "c": "A", "tp": "사업화 유형별 리스크와 수익"}, {"e": "IPAT 핵심", "i": "IPAT-4-1-2x", "t": "사업화 유형 중 벤처 창업은 리스크와 수익이 모두 가장 낮고 IP 매각은 모두 가장 높다.", "ox": "X", "c": "A", "tp": "사업화 유형별 리스크와 수익"}, {"e": "IPAT 핵심", "i": "IPAT-4-1-3o", "t": "스타트업 창업에서 지식재산권은 기술적 능력을 외부에 증명하는 수단이 되고 후발주자의 시장 진입을 차단하는 무기가 되며 기업가치 산정 시 무형자산으로 반영된다.", "ox": "O", "c": "A", "tp": "스타트업 창업과 지식재산권"}, {"e": "IPAT 핵심", "i": "IPAT-4-1-4o", "t": "지식재산의 사업화를 위해 새로운 스타트업을 설립하는 경우 리스크와 잠재수익이 모두 가장 높다.", "ox": "O", "c": "A", "tp": "스타트업 창업의 리스크"}, {"e": "IPAT 핵심", "i": "IPAT-4-1-4x", "t": "지식재산의 사업화를 위해 새로운 스타트업을 설립하는 경우 리스크는 가장 높지만 잠재수익은 가장 낮다.", "ox": "X", "c": "A", "tp": "스타트업 창업의 리스크"}, {"e": "IPAT 핵심", "i": "IPAT-4-1-5o", "t": "스타트업 창업의 리스크가 큰 이유는 지식재산이 제품으로 판매되기 전에 제품과 사업지원 인프라 개발을 위한 상당한 선행투자가 필요하기 때문이다.", "ox": "O", "c": "A", "tp": "스타트업 창업의 리스크 이유"}, {"e": "IPAT 핵심", "i": "IPAT-4-1-6o", "t": "기업 M&A는 기술적 경쟁 우위나 시장 점유율을 높이기 위해 상대 기업의 지식재산을 획득하는 것이 주된 목적이 될 수 있다.", "ox": "O", "c": "A", "tp": "기업 매수의 목적"}, {"e": "IPAT 핵심", "i": "IPAT-4-1-7o", "t": "기존 기업이나 사업부를 매수하면 대상이 이미 개발과 인적·물적 구조를 갖추고 있어 스타트업 창업보다 리스크가 낮고 사업화 기간이 단축되며 통제력을 유지할 수 있다.", "ox": "O", "c": "A", "tp": "기업 매수의 장점"}, {"e": "IPAT 핵심", "i": "IPAT-4-1-7x", "t": "기존 기업이나 사업부를 매수하면 스타트업 창업보다 리스크가 높고 사업화 기간이 더 길어진다.", "ox": "X", "c": "A", "tp": "기업 매수의 장점"}, {"e": "IPAT 핵심", "i": "IPAT-4-1-8o", "t": "기업 매수는 상당한 투자가 요구되어 잠재 수익이 감소하고, 기업문화 융합의 어려움과 원치 않는 자산·부채 인수 및 돌발채무의 부담이 따를 수 있다.", "ox": "O", "c": "A", "tp": "기업 매수의 단점"}, {"e": "IPAT 핵심", "i": "IPAT-4-1-8x", "t": "기업 매수는 투자 부담이 작아 잠재 수익이 오히려 커지며 기업문화 융합의 어려움이 거의 없다.", "ox": "X", "c": "A", "tp": "기업 매수의 단점"}], "2": [{"e": "IPAT 핵심", "i": "IPAT-4-2-1o", "t": "합작투자는 목표한 사업을 위해 참여 기업들이 지식재산을 공유하고 공동 목표를 위해 협력하는 투자 관계로, 조인트 벤처라고도 불린다.", "ox": "O", "c": "A", "tp": "합작투자의 의미"}, {"e": "IPAT 핵심", "i": "IPAT-4-2-2o", "t": "합작투자는 참여 기업의 보완적인 기술과 자원으로 리스크가 감소하지만, 리스크와 수익을 소유자 간에 나누므로 스타트업 설립이나 기업매수보다 수익은 낮아진다.", "ox": "O", "c": "A", "tp": "합작투자의 장단점"}, {"e": "IPAT 핵심", "i": "IPAT-4-2-2x", "t": "합작투자는 리스크와 수익을 나누지 않고 한 기업이 독점하므로 스타트업 설립보다 수익이 높아진다.", "ox": "X", "c": "A", "tp": "합작투자의 장단점"}, {"e": "IPAT 핵심", "i": "IPAT-4-2-3o", "t": "합작투자는 참여 기업 간의 상이한 목표와 지배력 수준 차이로 관리에 어려움이 있을 수 있다.", "ox": "O", "c": "A", "tp": "합작투자의 관리 어려움"}, {"e": "IPAT 핵심", "i": "IPAT-4-2-4o", "t": "전략적 제휴는 둘 이상의 기업이 각자의 지식재산을 공유하거나 상호 협력하여 새로운 시너지를 창출하기 위해 체결하며, 제휴에 따른 위험과 보상은 상호 협력 분야로 제한된다.", "ox": "O", "c": "A", "tp": "전략적 제휴의 목적"}, {"e": "IPAT 핵심", "i": "IPAT-4-2-5o", "t": "한 기업이 다른 기업이 개발한 제품을 시장에 판매하여 수익 일부를 얻는 것은 수직적 제휴이고, 특정 시장 공략을 위해 상대 기업의 전문화된 기술을 활용하는 것은 수평적 제휴이다.", "ox": "O", "c": "A", "tp": "수직적 제휴와 수평적 제휴"}, {"e": "IPAT 핵심", "i": "IPAT-4-2-5x", "t": "한 기업이 다른 기업이 개발한 제품을 시장에 판매하여 수익 일부를 얻는 것은 수평적 제휴이고, 상대 기업의 전문 기술을 활용하는 것은 수직적 제휴이다.", "ox": "X", "c": "A", "tp": "수직적 제휴와 수평적 제휴"}], "3": [{"e": "IPAT 핵심", "i": "IPAT-4-3-1o", "t": "라이선싱은 기술 보유자 입장에서는 자사 지식재산을 다른 기업에 이용 허가하여 수익을 창출하는 방법이고, 기술 도입자 입장에서는 기술적 과제를 해결하고 사업적 비전을 향상시키는 수단이다.", "ox": "O", "c": "A", "tp": "라이선싱의 의미"}, {"e": "IPAT 핵심", "i": "IPAT-4-3-1x", "t": "라이선싱은 기술 보유자에게만 경제적 수익이 생기고 기술 도입자에게는 아무런 이익이 없는 방법이다.", "ox": "X", "c": "A", "tp": "라이선싱의 의미"}, {"e": "IPAT 핵심", "i": "IPAT-4-3-2o", "t": "라이선싱은 앞서 설명한 사업화 유형들보다 리스크가 낮은데, 리스크 대부분이 제품 개발·제조·마케팅을 맡는 라이선시(기술도입자)에게 이전되기 때문이다.", "ox": "O", "c": "A", "tp": "라이선싱의 리스크"}, {"e": "IPAT 핵심", "i": "IPAT-4-3-2x", "t": "라이선싱은 리스크 대부분이 라이선서(기술제공자)에게 남아 다른 사업화 유형보다 리스크가 높다.", "ox": "X", "c": "A", "tp": "라이선싱의 리스크"}, {"e": "IPAT 핵심", "i": "IPAT-4-3-3o", "t": "라이선싱에서는 리스크가 이전되는 만큼 잠재수익도 라이선시에게 비례적으로 이전되어 라이선서의 수익은 줄어든다.", "ox": "O", "c": "A", "tp": "라이선싱의 수익"}, {"e": "IPAT 핵심", "i": "IPAT-4-3-4o", "t": "지식재산의 매각은 기술 보유자가 필요하지 않거나 부가가치를 창출하기 어려운 지식재산을 타 기업에 전달하는 방법으로, 무형자산을 처분하여 현금·주식·영업권 등을 확보할 수 있다.", "ox": "O", "c": "A", "tp": "지식재산의 매각"}, {"e": "IPAT 핵심", "i": "IPAT-4-3-5o", "t": "지식재산을 다른 기업에 바로 판매하는 것은 리스크가 가장 낮은 방법이지만 높은 리스크를 구매자에게 넘기는 것이므로 상대적으로 수익은 낮아진다.", "ox": "O", "c": "A", "tp": "매각의 리스크와 수익"}, {"e": "IPAT 핵심", "i": "IPAT-4-3-5x", "t": "지식재산을 다른 기업에 바로 판매하는 것은 리스크와 수익이 모두 가장 높은 방법이다.", "ox": "X", "c": "A", "tp": "매각의 리스크와 수익"}, {"e": "IPAT 핵심", "i": "IPAT-4-3-6o", "t": "스타트업이 아이디어 개발부터 시장 진입까지 직접 하기 어려우면 기술을 일정 수준까지 개발한 후 지식재산권을 대기업에 매각하며 기술을 지도하는 것을 사업 전략으로 취할 수 있다.", "ox": "O", "c": "A", "tp": "스타트업의 지식재산 매각 전략"}], "4": [{"e": "IPAT 핵심", "i": "IPAT-4-4-1o", "t": "기술창업은 혁신적인 기술이나 아이디어로 새 시장을 만들어 제품·서비스를 생산·판매하는 창업 형태로, 지식재산의 보호와 활용이 중요하다.", "ox": "O", "c": "A", "tp": "기술창업의 정의"}, {"e": "IPAT 핵심", "i": "IPAT-4-4-1x", "t": "기술창업은 노하우와 경험에 근거해 기존 시장에서 제품·서비스를 판매하는 창업 형태로, 지식재산의 역할은 크지 않다.", "ox": "X", "c": "A", "tp": "기술창업의 정의"}, {"e": "IPAT 핵심", "i": "IPAT-4-4-2o", "t": "기술창업은 대체로 제조업, 전문서비스업, 지식문화사업 분야의 창업을 뜻하지만 해당 기업군을 정의하는 일관된 용어는 없다.", "ox": "O", "c": "A", "tp": "기술창업의 범위"}, {"e": "IPAT 핵심", "i": "IPAT-4-4-3o", "t": "기술창업에서는 특허로 기술 혁신을 지키고, 상표로 제품과 브랜드를 식별하며, 저작권으로 창작물을 보호하는 전략을 쓴다.", "ox": "O", "c": "A", "tp": "기술창업의 지식재산 전략"}, {"e": "IPAT 핵심", "i": "IPAT-4-4-3x", "t": "기술창업에서는 특허로 브랜드를 식별하고, 상표로 기술 혁신을 보호하며, 저작권으로 창작물을 지키는 전략을 쓴다.", "ox": "X", "c": "A", "tp": "기술창업의 지식재산 전략"}, {"e": "IPAT 핵심", "i": "IPAT-4-4-4o", "t": "기술창업은 일반창업보다 독점성과 경쟁력이 강한 반면 기술수명주기가 있어 오래 유지하기 어렵다는 특성이 있다.", "ox": "O", "c": "A", "tp": "기술창업의 특성"}, {"e": "IPAT 핵심", "i": "IPAT-4-4-4x", "t": "기술창업은 일반창업보다 독점성과 경쟁력이 강하고 기술수명주기가 없어 오래 유지하기 쉽다는 특성이 있다.", "ox": "X", "c": "A", "tp": "기술창업의 특성"}, {"e": "IPAT 핵심", "i": "IPAT-4-4-5o", "t": "지식기술창업의 범주에는 주로 IT융합 분야의 콘텐츠·소프트웨어, 제조업 융합 분야, 지식 기반 서비스업이 포함되고 생계형 창업은 제외하는 것이 일반적이다.", "ox": "O", "c": "A", "tp": "지식기술창업의 범주"}, {"e": "IPAT 핵심", "i": "IPAT-4-4-5x", "t": "지식기술창업의 범주에는 주로 IT융합 분야의 콘텐츠·소프트웨어와 함께 생계형 창업과 전통 제조 분야 창업도 포함하는 것이 일반적이다.", "ox": "X", "c": "A", "tp": "지식기술창업의 범주"}], "5": [{"e": "IPAT 핵심", "i": "IPAT-4-5-1o", "t": "기술창업에서는 아이템 사업화를 가능하게 하는 핵심 기술인력을 확보하지 못하면 창업 자체가 불가능할 수 있다.", "ox": "O", "c": "A", "tp": "핵심 기술인력 확보"}, {"e": "IPAT 핵심", "i": "IPAT-4-5-1x", "t": "기술창업에서는 아이템 사업화를 가능하게 하는 핵심 기술인력을 확보하지 못하더라도 외주 인력으로 창업 자체는 항상 가능하다.", "ox": "X", "c": "A", "tp": "핵심 기술인력 확보"}, {"e": "IPAT 핵심", "i": "IPAT-4-5-2o", "t": "창업 초기에는 사업성 있는 아이템을 포착하고 기술을 사업화할 역량이 중요한데, 많은 기업이 이 역량 확보에 실패한다.", "ox": "O", "c": "A", "tp": "창업 초기 역량"}, {"e": "IPAT 핵심", "i": "IPAT-4-5-2x", "t": "창업 초기에는 사업성 있는 아이템을 포착하는 역량보다 대규모 설비투자 능력이 가장 중요하다.", "ox": "X", "c": "A", "tp": "창업 초기 역량"}, {"e": "IPAT 핵심", "i": "IPAT-4-5-3o", "t": "기술창업 초기에는 매출이 적어 기술 수준과 성장성 같은 무형의 가치를 평가받아야 하지만 이를 위한 시스템이 취약하다.", "ox": "O", "c": "A", "tp": "무형가치 평가와 회수시장"}, {"e": "IPAT 핵심", "i": "IPAT-4-5-3x", "t": "기술창업 초기에는 매출이 크게 발생하므로 유형 자산 위주의 평가 시스템만으로도 충분히 가치를 평가받을 수 있다.", "ox": "X", "c": "A", "tp": "무형가치 평가와 회수시장"}, {"e": "IPAT 핵심", "i": "IPAT-4-5-4o", "t": "기술창업에서는 각종 절차와 규제에서 생기는 비용이 진입장벽이 되며, 사업화에 필요한 인허가·규제도 유무형의 비용으로 작용한다.", "ox": "O", "c": "A", "tp": "제도·행정 진입장벽"}, {"e": "IPAT 핵심", "i": "IPAT-4-5-5o", "t": "제도적 검토 없이 사업을 시작하면 제품이 나와도 시장에 출시할 수 없는 문제가 생길 수 있으므로 법적 구조와 규제 준수 확인이 필요하다.", "ox": "O", "c": "A", "tp": "법적 구조와 규제 준수"}], "6": [{"e": "IPAT 핵심", "i": "IPAT-4-6-1o", "t": "기술창업의 기본 절차는 사업 아이템을 정하고 객관적 검증을 거쳐 실현 가능한 계획을 세운 뒤 창업을 실현하는 과정이다.", "ox": "O", "c": "A", "tp": "기술창업의 기본 절차"}, {"e": "IPAT 핵심", "i": "IPAT-4-6-2o", "t": "기술창업 기본 절차는 창업구상 단계, 창업계획 단계, 사업실행 단계의 순서로 이어진다.", "ox": "O", "c": "A", "tp": "창업 3단계"}, {"e": "IPAT 핵심", "i": "IPAT-4-6-2x", "t": "기술창업 기본 절차는 창업계획 단계, 창업구상 단계, 사업실행 단계의 순서로 이어진다.", "ox": "X", "c": "A", "tp": "창업 3단계"}, {"e": "IPAT 핵심", "i": "IPAT-4-6-3o", "t": "창업구상 단계는 구체적인 아이템을 정하기 전에 창업자의 역량을 점검하고 시장·기술 조사로 가장 적합한 아이템을 구상하는 단계이다.", "ox": "O", "c": "A", "tp": "창업구상 단계"}, {"e": "IPAT 핵심", "i": "IPAT-4-6-3x", "t": "창업구상 단계는 회사를 설립하고 공장을 짓는 등 선정된 창업 아이템의 사업화를 진행하는 단계이다.", "ox": "X", "c": "A", "tp": "창업구상 단계"}, {"e": "IPAT 핵심", "i": "IPAT-4-6-4o", "t": "창업계획 단계는 사업 타당성 검토와 사전계획 수립으로 시행착오를 줄이고 사업계획서를 작성하는 단계이다.", "ox": "O", "c": "A", "tp": "창업계획 단계"}, {"e": "IPAT 핵심", "i": "IPAT-4-6-4x", "t": "사업실행 단계는 사업 타당성 검토와 사전계획 수립으로 시행착오를 줄이고 사업계획서를 작성하는 단계이다.", "ox": "X", "c": "A", "tp": "창업계획 단계"}, {"e": "IPAT 핵심", "i": "IPAT-4-6-5o", "t": "사업실행 단계는 선정된 창업 아이템의 사업화를 위해 회사 설립, 공장 설립, 조직·인력 확보, 경영관리를 진행하는 단계이다.", "ox": "O", "c": "A", "tp": "사업실행 단계"}, {"e": "IPAT 핵심", "i": "IPAT-4-6-6o", "t": "창업구상 단계에는 사업 아이템 탐색 뒤에 선행기술 조사, 법적 문제점 검토, 지식재산 출원을 하는 지식재산 조사 분석이 포함된다.", "ox": "O", "c": "A", "tp": "창업구상 단계의 지식재산 조사"}], "7": [{"e": "IPAT 핵심", "i": "IPAT-4-7-1o", "t": "창업보육센터(인큐베이터)는 초기 창업자에게 사무 공간, 멘토링, 자금 지원, 네트워킹 기회 등을 제공해 창업을 돕는다.", "ox": "O", "c": "A", "tp": "창업보육센터"}, {"e": "IPAT 핵심", "i": "IPAT-4-7-1x", "t": "창업보육센터(인큐베이터)는 이미 성숙기에 접어든 대기업에 사무 공간, 멘토링, 자금 지원, 네트워킹 기회를 제공한다.", "ox": "X", "c": "A", "tp": "창업보육센터"}, {"e": "IPAT 핵심", "i": "IPAT-4-7-2o", "t": "스핀오프 창업은 기존 기업이나 연구기관이 개발한 기술을 이전받아 독립 회사를 세우는 형태로 기술적 리스크가 상대적으로 낮다.", "ox": "O", "c": "A", "tp": "스핀오프 창업"}, {"e": "IPAT 핵심", "i": "IPAT-4-7-2x", "t": "스핀오프 창업은 기존 기업이나 연구기관이 개발한 기술을 이전받아 독립 회사를 세우는 형태로 기술적 리스크가 상대적으로 높다.", "ox": "X", "c": "A", "tp": "스핀오프 창업"}, {"e": "IPAT 핵심", "i": "IPAT-4-7-3o", "t": "기술지주회사는 대학이나 연구기관이 보유한 기술의 상용화를 위해 설립된 회사로 기술이전과 사업화를 전문적으로 지원한다.", "ox": "O", "c": "A", "tp": "기술지주회사"}, {"e": "IPAT 핵심", "i": "IPAT-4-7-3x", "t": "기술지주회사는 창업자가 직접 설립하는 일반 제조회사로 기술이전과 사업화는 정부 기관이 전담 지원한다.", "ox": "X", "c": "A", "tp": "기술지주회사"}, {"e": "IPAT 핵심", "i": "IPAT-4-7-4o", "t": "예비창업패키지, 초기창업패키지, 청년창업사관학교, TIPS 같은 정부 창업지원 매칭자금으로 초기 창업자금을 확보하는 형태도 있다.", "ox": "O", "c": "A", "tp": "정부지원사업을 통한 창업"}, {"e": "IPAT 핵심", "i": "IPAT-4-7-5o", "t": "기술창업에서는 스톡옵션제도로 인재를 영입하고, B2G 사업 확대를 위해 NET·NEP 인증제도를 활용하는 것도 전략이 될 수 있다.", "ox": "O", "c": "A", "tp": "기술창업의 기타 전략"}, {"e": "IPAT 핵심", "i": "IPAT-4-7-5x", "t": "기술창업에서는 스톡옵션제도로 인재를 영입하고, B2C 사업 확대를 위해 NET·NEP 인증제도를 활용하는 것도 전략이 될 수 있다.", "ox": "X", "c": "A", "tp": "기술창업의 기타 전략"}], "8": [{"e": "IPAT 핵심", "i": "IPAT-4-8-1o", "t": "창업의 성공적 수행에는 사람, 아이디어, 시장, 자본이라는 요소가 필요하며 이 요소들이 상호작용해 성공 여부를 좌우한다.", "ox": "O", "c": "A", "tp": "창업의 핵심요소"}, {"e": "IPAT 핵심", "i": "IPAT-4-8-1x", "t": "창업의 성공적 수행에는 사람, 아이디어, 시장, 정부 인증이라는 네 요소가 필요하다.", "ox": "X", "c": "A", "tp": "창업의 핵심요소"}, {"e": "IPAT 핵심", "i": "IPAT-4-8-2o", "t": "동업자는 창업자와 함께 금전·현물·기술을 투자하고 사업부문별 역할을 맡아 그 과실을 분배받는 사람으로 창업자 다음으로 중요한 구성원이다.", "ox": "O", "c": "A", "tp": "동업자"}, {"e": "IPAT 핵심", "i": "IPAT-4-8-2x", "t": "창업기업의 팀원은 금전·현물·기술을 투자하고 사업 과실을 분배받는 사람으로 창업자 다음으로 중요한 구성원이다.", "ox": "X", "c": "A", "tp": "동업자"}, {"e": "IPAT 핵심", "i": "IPAT-4-8-3o", "t": "기술창업의 아이디어는 혁신성과 실현 가능성을 갖추어야 하며, 지식재산권 확보가 가능한 아이디어가 경쟁우위와 투자 유치에 좋다.", "ox": "O", "c": "A", "tp": "기술창업 아이디어"}, {"e": "IPAT 핵심", "i": "IPAT-4-8-4o", "t": "시장은 제품·서비스에 대가를 지급하고 구입하려는 고객 집단으로, 시장 가능성을 보고 제품을 개발하는 쪽이 기술 우수성만 믿고 개발하는 것보다 성공 가능성이 높다.", "ox": "O", "c": "A", "tp": "시장 요소"}, {"e": "IPAT 핵심", "i": "IPAT-4-8-5o", "t": "자기자본은 조달된 자본 중 상환 의무가 없는 자본으로, 법인기업에서는 주주나 출자자가 투자한 금액을 말한다.", "ox": "O", "c": "A", "tp": "자기자본"}, {"e": "IPAT 핵심", "i": "IPAT-4-8-5x", "t": "자기자본은 금융기관 차입 등으로 조달하는 자본으로 상환 의무가 있다.", "ox": "X", "c": "A", "tp": "자기자본"}, {"e": "IPAT 핵심", "i": "IPAT-4-8-6o", "t": "타인자본은 친인척·지인·금융기관 차입처럼 주주나 출자자 투자 이외에 타인으로부터 조달하는 자금으로 상환 의무가 있다.", "ox": "O", "c": "A", "tp": "타인자본"}, {"e": "IPAT 핵심", "i": "IPAT-4-8-6x", "t": "타인자본은 친인척·지인·금융기관에서 조달한 자금이지만 상환 의무가 없는 자본이다.", "ox": "X", "c": "A", "tp": "타인자본"}, {"e": "IPAT 핵심", "i": "IPAT-4-8-7o", "t": "기술창업의 초기 자본은 주로 엔젤 투자자, 벤처캐피털, 정부 지원 프로그램을 통해 조달하는 것이 일반적이다.", "ox": "O", "c": "A", "tp": "초기 자본 조달"}, {"e": "IPAT 핵심", "i": "IPAT-4-8-7x", "t": "기술창업의 초기 자본은 주로 상장 후 공모 증자를 통해 조달하는 것이 일반적이다.", "ox": "X", "c": "A", "tp": "초기 자본 조달"}, {"e": "IPAT 핵심", "i": "IPAT-4-8-8o", "t": "비즈니스 모델은 수익을 창출할 수 있는 명확하고 실현 가능한 모델로, 가격 책정, 판매 전략, 수익 구조 등을 포함한다.", "ox": "O", "c": "A", "tp": "비즈니스 모델"}], "9": [{"e": "IPAT 핵심", "i": "IPAT-4-9-1o", "t": "전통적으로 M&A는 규모의 경제와 시장점유율 확대가 목적이었으나 최근에는 지식재산이 M&A의 주요 요인으로 작용하고 있다.", "ox": "O", "c": "A", "tp": "M&A와 지식재산"}, {"e": "IPAT 핵심", "i": "IPAT-4-9-1x", "t": "전통적으로 M&A는 지식재산 확보가 주된 목적이었으나 최근에는 규모의 경제와 시장점유율 확대가 주요 요인으로 작용하고 있다.", "ox": "X", "c": "A", "tp": "M&A와 지식재산"}, {"e": "IPAT 핵심", "i": "IPAT-4-9-2o", "t": "독점적 이익을 얻기 위한 M&A는 다른 기업의 지식재산을 획득해 독점적 기술·제품을 보유하고 경쟁사보다 우월한 위치를 차지하려는 동기이다.", "ox": "O", "c": "A", "tp": "독점적 이익 동기"}, {"e": "IPAT 핵심", "i": "IPAT-4-9-2x", "t": "독점적 이익을 얻기 위한 M&A는 원재료 공급부터 판매까지 장악해 협상·조정 비용을 줄이려는 동기이다.", "ox": "X", "c": "A", "tp": "독점적 이익 동기"}, {"e": "IPAT 핵심", "i": "IPAT-4-9-3o", "t": "원재료 공급부터 판매까지 장악하는 수직적 합병은 협상·조정·커뮤니케이션 비용과 광고·포장 비용을 줄일 수 있어 효율적 통제를 위한 동기가 된다.", "ox": "O", "c": "A", "tp": "효율적 통제 동기"}, {"e": "IPAT 핵심", "i": "IPAT-4-9-3x", "t": "서로 다른 산업의 기업을 합병하는 수평적 합병은 원재료 공급부터 판매까지 장악하여 비용을 줄이는 효율적 통제 동기이다.", "ox": "X", "c": "A", "tp": "효율적 통제 동기"}, {"e": "IPAT 핵심", "i": "IPAT-4-9-4o", "t": "채산성이 없거나 성장률이 낮을 것으로 예상되는 지식재산을 매각하고 주력업종에 집중하려는 것이 수익성 확보를 위한 M&A 동기이다.", "ox": "O", "c": "A", "tp": "수익성 확보 동기"}, {"e": "IPAT 핵심", "i": "IPAT-4-9-4x", "t": "수익성 확보를 위한 M&A는 성장률이 높을 것으로 예상되는 핵심 지식재산을 매각하고 비주력 사업에 집중하려는 동기이다.", "ox": "X", "c": "A", "tp": "수익성 확보 동기"}, {"e": "IPAT 핵심", "i": "IPAT-4-9-5o", "t": "M&A로 기업은 규모의 경제와 범위의 경제를 실현하고 기술과 자원의 시너지를 극대화해 효율성을 높일 수 있다.", "ox": "O", "c": "A", "tp": "효율성 극대화 동기"}, {"e": "IPAT 핵심", "i": "IPAT-4-9-5x", "t": "M&A로 기업은 초기의 수익 추구를 위한 단기적 머니게임을 극대화해 효율성을 높일 수 있다.", "ox": "X", "c": "A", "tp": "효율성 극대화 동기"}, {"e": "IPAT 핵심", "i": "IPAT-4-9-6o", "t": "M&A로 지리적 다변화와 새 고객층 확보를 이루고 여러 시장에 리스크를 분산해 안정적 성장을 꾀할 수 있다.", "ox": "O", "c": "A", "tp": "시장 다변화 동기"}, {"e": "IPAT 핵심", "i": "IPAT-4-9-6x", "t": "M&A로 시장 다변화를 하면 특정 시장에 위험을 집중시켜 안정적 성장을 꾀할 수 있다.", "ox": "X", "c": "A", "tp": "시장 다변화 동기"}, {"e": "IPAT 핵심", "i": "IPAT-4-9-7o", "t": "신기술을 보유한 기업을 인수하면 내부 기술 개발에 드는 시간과 비용을 절감하고 빠르게 변하는 시장에서 혁신을 주도할 수 있다.", "ox": "O", "c": "A", "tp": "기술 및 혁신 확보 동기"}, {"e": "IPAT 핵심", "i": "IPAT-4-9-8o", "t": "M&A로 인수 대상 기업의 전문인력과 인재를 자사로 흡수해 인적 자원의 질을 높이고 핵심 역량을 강화할 수 있다.", "ox": "O", "c": "A", "tp": "인재 확보 동기"}, {"e": "IPAT 핵심", "i": "IPAT-4-9-9o", "t": "시장 내 경쟁자를 제거하거나 약화시키기 위해 M&A를 하면 시장점유율을 높이고 가격 책정 등에서 우위를 점할 수 있다.", "ox": "O", "c": "A", "tp": "경쟁 제거 동기"}, {"e": "IPAT 핵심", "i": "IPAT-4-9-9x", "t": "M&A로 경쟁자를 제거하면 시장점유율은 높일 수 있지만 가격 책정 면에서의 우위는 얻을 수 없다.", "ox": "X", "c": "A", "tp": "경쟁 제거 동기"}], "10": [{"e": "IPAT 핵심", "i": "IPAT-4-10-1o", "t": "M&A에서 보유 지식재산은 대상 기업에 대한 중요한 실사 항목 중 하나이다.", "ox": "O", "c": "A", "tp": "M&A 시 지식재산 실사"}, {"e": "IPAT 핵심", "i": "IPAT-4-10-2o", "t": "M&A에서는 개별 지식재산보다 기업 전체의 가치를 평가하는 것이 합리적인데, M&A가 기업의 개별 이전이 아닌 포괄적 이전이기 때문이다.", "ox": "O", "c": "A", "tp": "M&A 가치평가"}, {"e": "IPAT 핵심", "i": "IPAT-4-10-2x", "t": "M&A에서는 기업 전체의 가치보다 개별 지식재산의 가치를 평가하는 것이 합리적인데, M&A가 개별적 이전이기 때문이다.", "ox": "X", "c": "A", "tp": "M&A 가치평가"}, {"e": "IPAT 핵심", "i": "IPAT-4-10-3o", "t": "M&A 과정에서 매입 대상 기업이 소유하거나 사용하는 지식재산은 자산실사(due diligence)를 통해 조사해야 한다.", "ox": "O", "c": "A", "tp": "자산실사"}, {"e": "IPAT 핵심", "i": "IPAT-4-10-3x", "t": "M&A 과정에서 매입 대상 기업이 소유한 지식재산은 자산실사 대신 매각 후 사후 검토로 조사한다.", "ox": "X", "c": "A", "tp": "자산실사"}, {"e": "IPAT 핵심", "i": "IPAT-4-10-4o", "t": "M&A 실사에서는 대상 IP가 법적 논란이나 침해 분쟁에 휘말리지 않았는지 확인해 매입 후 법적 리스크를 최소화해야 한다.", "ox": "O", "c": "A", "tp": "IP 합법성과 침해 분쟁"}, {"e": "IPAT 핵심", "i": "IPAT-4-10-5o", "t": "등록된 IP의 보호기간이 곧 만료될 가능성이 있으면 가치를 재평가하거나 만료를 기다려 실시하는 방안을 검토한다.", "ox": "O", "c": "A", "tp": "보호기간 확인"}, {"e": "IPAT 핵심", "i": "IPAT-4-10-5x", "t": "등록된 IP의 보호기간이 곧 만료될 가능성이 있으면 보호기간과 관계없이 원래 평가액 그대로 매입한다.", "ox": "X", "c": "A", "tp": "보호기간 확인"}, {"e": "IPAT 핵심", "i": "IPAT-4-10-6o", "t": "매입 대상 기업이 다른 회사와 공유하는 IP는 구매자가 소유하고 라이선스를 판매자에게 줄지, 그 반대로 할지 명확히 합의해야 한다.", "ox": "O", "c": "A", "tp": "공유 IP 처리"}], "11": [{"e": "IPAT 핵심", "i": "IPAT-4-11-1o", "t": "M&A를 통한 특허 전략은 성장 전략, 유지 전략, 처분 전략으로 나눌 수 있다.", "ox": "O", "c": "A", "tp": "M&A 3대 전략"}, {"e": "IPAT 핵심", "i": "IPAT-4-11-2o", "t": "성장 전략은 제품라인 개발이나 신규 시장 확장 같은 장기 문제와 관련되며, 향후 18개월에서 5년의 경쟁 상황에 초점을 둔다.", "ox": "O", "c": "A", "tp": "성장 전략의 개념"}, {"e": "IPAT 핵심", "i": "IPAT-4-11-2x", "t": "성장 전략은 낮은 이윤 같은 당면 문제의 해결과 관련되며, 향후 12~18개월의 경쟁 상황에 초점을 둔다.", "ox": "X", "c": "A", "tp": "성장 전략의 개념"}, {"e": "IPAT 핵심", "i": "IPAT-4-11-3o", "t": "성장 전략에서는 M&A로 새로운 시장의 특허를 획득해 그 시장에 성공적으로 진입할 수 있다.", "ox": "O", "c": "A", "tp": "성장 전략의 방법"}, {"e": "IPAT 핵심", "i": "IPAT-4-11-4o", "t": "TI는 Amati Communications를 인수해 25개의 DSL 특허를 얻었고, 이 특허가 DSL 기술표준으로 채택되어 시장을 선도했다.", "ox": "O", "c": "A", "tp": "성장 전략 사례(TI)"}, {"e": "IPAT 핵심", "i": "IPAT-4-11-5o", "t": "유지 전략은 낮은 성장률이나 이윤 축소 같은 당면 문제를 해결하기 위해 12~18개월 정도 걸리는 방안을 제시하며 이윤 제고와 수입 증대를 목표로 한다.", "ox": "O", "c": "A", "tp": "유지 전략의 개념"}, {"e": "IPAT 핵심", "i": "IPAT-4-11-5x", "t": "유지 전략은 신규 시장 확장 같은 장기 문제를 해결하기 위해 18개월에서 5년 정도 걸리는 방안을 제시하며 이윤 제고와 수입 증대를 목표로 한다.", "ox": "X", "c": "A", "tp": "유지 전략의 개념"}, {"e": "IPAT 핵심", "i": "IPAT-4-11-6o", "t": "유지 전략에서는 특허위치에서 경쟁력이 약한 부분을 강화하고 자사 보유특허를 상호 라이선싱이나 로열티 획득 수단으로 활용한다.", "ox": "O", "c": "A", "tp": "유지 전략의 수단"}, {"e": "IPAT 핵심", "i": "IPAT-4-11-7o", "t": "Canon은 잉크젯 카트리지, 용지 등 프린터 소모품 관련 기술을 모두 특허화하는 유지 전략으로 프린터 시장의 우위를 지켰다.", "ox": "O", "c": "A", "tp": "유지 전략 사례(Canon)"}, {"e": "IPAT 핵심", "i": "IPAT-4-11-8o", "t": "처분 전략은 경영실적이 나쁘거나 비전이 없는 사업의 특허, 주력 사업과 관련성이 낮은 특허 등을 타사에 판매해 수익 기회를 만드는 전략이다.", "ox": "O", "c": "A", "tp": "처분 전략의 개념"}, {"e": "IPAT 핵심", "i": "IPAT-4-11-8x", "t": "처분 전략은 주력 사업과 관련성이 높은 핵심 특허를 타사에 판매해 수익 기회를 만드는 전략이다.", "ox": "X", "c": "A", "tp": "처분 전략의 개념"}, {"e": "IPAT 핵심", "i": "IPAT-4-11-9o", "t": "Avery Dennison은 경쟁사의 강력한 특허 때문에 힘을 못 쓰던 사업의 특허를 처분하고, 그 수입을 성장 중인 사업에 재투자했다.", "ox": "O", "c": "A", "tp": "처분 전략 사례"}], "12": [{"e": "IPAT 핵심", "i": "IPAT-4-12-1o", "t": "IP 라이선싱은 지식재산권 소유자가 다른 개인이나 기업에 해당 권리를 사용할 수 있는 권한을 부여하는 계약이며, 권리 양도와는 다르다.", "ox": "O", "c": "A", "tp": "IP 라이선싱의 정의"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-1x", "t": "IP 라이선싱은 지식재산권 소유권 자체를 다른 개인이나 기업에 넘기는 양도 계약이다.", "ox": "X", "c": "A", "tp": "IP 라이선싱의 정의"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-2o", "t": "독점 라이선스는 특정 라이선시에게만 사용 권한을 주고 다른 누구에게도 같은 권한을 주지 않으며, 비독점 라이선스는 여러 라이선시에게 같은 지식재산 사용을 허용한다.", "ox": "O", "c": "A", "tp": "독점·비독점 라이선스"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-2x", "t": "독점 라이선스는 여러 라이선시에게 같은 지식재산 사용을 허용하고, 비독점 라이선스는 특정 라이선시에게만 사용 권한을 준다.", "ox": "X", "c": "A", "tp": "독점·비독점 라이선스"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-3o", "t": "독점 라이선스라도 지역, 기간, 제품·서비스 영역 등을 제한해 허여하는 경우가 있어 분쟁 소지를 막으려면 영역을 잘 설정해야 한다.", "ox": "O", "c": "A", "tp": "독점 라이선스의 제한"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-4o", "t": "라이선스를 주는 자가 라이선서(licensor)이고 라이선스를 받는 자가 라이선시(licensee)이다.", "ox": "O", "c": "A", "tp": "라이선서와 라이선시"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-4x", "t": "라이선스를 주는 자가 라이선시(licensee)이고 라이선스를 받는 자가 라이선서(licensor)이다.", "ox": "X", "c": "A", "tp": "라이선서와 라이선시"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-5o", "t": "라이선싱 아웃은 라이선스를 타인에게 주는 것이고, 라이선싱 인은 타인의 권리에 대해 라이선스를 도입하는 것이다.", "ox": "O", "c": "A", "tp": "라이선싱 아웃과 인"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-5x", "t": "라이선싱 인은 라이선스를 타인에게 주는 것이고, 라이선싱 아웃은 타인의 권리에 대해 라이선스를 도입하는 것이다.", "ox": "X", "c": "A", "tp": "라이선싱 아웃과 인"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-6o", "t": "특허권의 전용실시권은 등록이 효력 발생요건이고, 통상실시권은 계약에 의한 합의만으로 효력이 발생한다.", "ox": "O", "c": "A", "tp": "전용실시권의 효력 발생"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-6x", "t": "특허권의 통상실시권은 등록이 효력 발생요건이고, 전용실시권은 계약에 의한 합의만으로 효력이 발생한다.", "ox": "X", "c": "A", "tp": "전용실시권의 효력 발생"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-7o", "t": "전용실시권이 설정·등록되면 그 범위 안에서는 특허권자도 특허발명을 실시할 수 없고 전용실시권자가 실시할 권리를 독점한다.", "ox": "O", "c": "A", "tp": "전용실시권의 독점"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-7x", "t": "전용실시권이 설정·등록되더라도 그 범위 안에서 특허권자는 특허발명을 계속 실시할 수 있다.", "ox": "X", "c": "A", "tp": "전용실시권의 독점"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-8o", "t": "계약에 의한 실시권은 사적 자치의 원칙에 따라 기간을 한정하거나 실시 지역, 실시 제품 또는 형태를 한정해 설정할 수 있다.", "ox": "O", "c": "A", "tp": "실시권 설정 조건"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-8x", "t": "계약에 의한 실시권은 기간·지역·제품 형태를 한정할 수 없고 전면 허락만 가능하다.", "ox": "X", "c": "A", "tp": "실시권 설정 조건"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-9o", "t": "양자 간 계약으로 체결되는 폐쇄형 라이선스는 라이선시만 권리를 쓸 수 있지만, 개방형 라이선스는 일정 조건 아래 공개되어 누구나 이용할 수 있다.", "ox": "O", "c": "A", "tp": "폐쇄형·개방형 라이선스"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-9x", "t": "양자 간 계약으로 체결되는 개방형 라이선스는 라이선시만 권리를 쓸 수 있지만, 폐쇄형 라이선스는 누구나 이용할 수 있다.", "ox": "X", "c": "A", "tp": "폐쇄형·개방형 라이선스"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-10o", "t": "개방형 라이선스는 주로 소프트웨어 분야에서 쓰이며, 오픈소스 소프트웨어는 자유롭게 이용·복제·재배포·수정할 수 있는 것이 특징이다.", "ox": "O", "c": "A", "tp": "오픈소스 소프트웨어"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-11o", "t": "묵시적 라이선스는 정당한 권한자가 특허제품을 정당하게 유통했을 때 구매자에게 권리자가 침해를 주장할 수 없게 되는 것으로, 권리 소진 법리에 따른다.", "ox": "O", "c": "A", "tp": "묵시적 라이선스"}, {"e": "IPAT 핵심", "i": "IPAT-4-12-11x", "t": "묵시적 라이선스는 권리자의 의사에 기반한 계약으로 발생하며 권리 소진의 법리와는 무관하다.", "ox": "X", "c": "A", "tp": "묵시적 라이선스"}], "13": [{"e": "IPAT 핵심", "i": "IPAT-4-13-1o", "t": "라이선서는 기술을 직접 제공하지 않고도 수익을 얻고, 라이선시는 해당 기술로 제품을 개발할 수 있어 중소기업과 스타트업에 중요한 전략 수단이 된다.", "ox": "O", "c": "A", "tp": "라이선싱 계약의 이점"}, {"e": "IPAT 핵심", "i": "IPAT-4-13-2o", "t": "라이선시는 필요한 기술의 권리를 받아 제품 가치를 높이고, 해당 권리로 인한 분쟁 위험도 제거해 안정적으로 사업을 할 수 있다.", "ox": "O", "c": "A", "tp": "라이선시 측 효과"}, {"e": "IPAT 핵심", "i": "IPAT-4-13-2x", "t": "라이선시는 라이선스를 받아도 해당 권리에서 비롯되는 분쟁 위험은 그대로 부담한다.", "ox": "X", "c": "A", "tp": "라이선시 측 효과"}, {"e": "IPAT 핵심", "i": "IPAT-4-13-3o", "t": "라이선서는 라이선시의 실시에 따른 실시료를 징수해 수익을 얻으며, 경상실시료로 합의하면 라이선시의 매출이 늘수록 실시료 수입도 늘어난다.", "ox": "O", "c": "A", "tp": "라이선서 측 효과(실시료)"}, {"e": "IPAT 핵심", "i": "IPAT-4-13-4o", "t": "라이선서는 라이선시의 영업을 통해 새 시장에 진입할 수 있고, 새 시장 진입에 따른 설비 투자 비용과 사업 불확실성은 라이선시가 부담하게 된다.", "ox": "O", "c": "A", "tp": "라이선서의 시장 진입 효과"}, {"e": "IPAT 핵심", "i": "IPAT-4-13-4x", "t": "라이선서는 라이선시의 영업을 통해 새 시장에 진입할 수 있고, 새 시장 진입에 따른 설비 투자 비용과 사업 불확실성은 라이선서가 부담하게 된다.", "ox": "X", "c": "A", "tp": "라이선서의 시장 진입 효과"}, {"e": "IPAT 핵심", "i": "IPAT-4-13-5o", "t": "라이선시도 유용한 특허를 가진 경우 크로스 라이선스로 서로 사용하게 할 수 있고, 제3자 권리 침해 시에도 공동 대응으로 분쟁 대응 역량을 강화할 수 있다.", "ox": "O", "c": "A", "tp": "크로스 라이선스의 효과"}, {"e": "IPAT 핵심", "i": "IPAT-4-13-6o", "t": "라이선서는 라이선시와 공동 개발·마케팅으로 라이선스 대상 기술이 산업 표준이 되도록 노력할 수 있고 실질적 표준 기술이 되게 할 수도 있다.", "ox": "O", "c": "A", "tp": "기술의 표준화 효과"}, {"e": "IPAT 핵심", "i": "IPAT-4-13-6x", "t": "라이선서는 표준으로 선정되지 않는 한 라이선스 대상 기술이 실질적 표준이 되도록 할 수 없다.", "ox": "X", "c": "A", "tp": "기술의 표준화 효과"}, {"e": "IPAT 핵심", "i": "IPAT-4-13-7o", "t": "라이선싱 활동은 관련 시장 확대와 기술개발 가속으로 기업 가치를 높이는 개방형 혁신의 일종으로 볼 수 있다.", "ox": "O", "c": "A", "tp": "라이선싱과 개방형 혁신"}], "14": [{"e": "IPAT 핵심", "i": "IPAT-4-14-1o", "t": "라이선싱 계약의 조건에는 사용 범위, 사용 기간, 지불 방식, 지식재산의 유지·보호에 관한 사항이 포함되며 양측의 협상으로 정한다.", "ox": "O", "c": "A", "tp": "라이선싱 계약 조건"}, {"e": "IPAT 핵심", "i": "IPAT-4-14-1x", "t": "라이선싱 계약의 조건은 법령으로 일률적으로 정해지며 양측의 협상 여지는 없다.", "ox": "X", "c": "A", "tp": "라이선싱 계약 조건"}, {"e": "IPAT 핵심", "i": "IPAT-4-14-2o", "t": "라이선스 계약의 필수요소는 계약 당사자, 실시허락의 대상 기술, 실시권의 세 가지이며, 실시료는 법적 필수요소가 아니다.", "ox": "O", "c": "A", "tp": "라이선스 계약의 정의와 필수요소"}, {"e": "IPAT 핵심", "i": "IPAT-4-14-2x", "t": "라이선스 계약의 필수요소는 계약 당사자, 대상 기술, 실시권, 실시료의 네 가지이며 무상 계약은 라이선스 계약이 아니다.", "ox": "X", "c": "A", "tp": "라이선스 계약의 정의와 필수요소"}, {"e": "IPAT 핵심", "i": "IPAT-4-14-3o", "t": "라이선스 계약은 계약자유의 원칙에 따라 전용실시인지 통상실시인지를 가리지 않고 합의만으로 성립하며 제3자의 동의나 행정청의 허가·등록이 필요 없다.", "ox": "O", "c": "A", "tp": "계약의 성립"}, {"e": "IPAT 핵심", "i": "IPAT-4-14-3x", "t": "전용실시 라이선스 계약은 합의만으로는 성립하지 않으며 행정청의 허가가 있어야 비로소 성립한다.", "ox": "X", "c": "A", "tp": "계약의 성립"}, {"e": "IPAT 핵심", "i": "IPAT-4-14-4o", "t": "공유특허권자는 다른 공유자의 동의를 받지 않으면 제3자에게 실시권을 허락할 수 없다.", "ox": "O", "c": "A", "tp": "공유특허의 실시허락 제한"}, {"e": "IPAT 핵심", "i": "IPAT-4-14-4x", "t": "공유특허권자는 다른 공유자의 동의 없이도 제3자에게 자유롭게 실시권을 허락할 수 있다.", "ox": "X", "c": "A", "tp": "공유특허의 실시허락 제한"}, {"e": "IPAT 핵심", "i": "IPAT-4-14-5o", "t": "국제 라이선스 계약이나 기술도입 계약을 체결할 때는 주무관청이나 공정거래위원회에 소정 사항을 신고해야 하는 경우도 있다.", "ox": "O", "c": "A", "tp": "국제 라이선스 신고"}, {"e": "IPAT 핵심", "i": "IPAT-4-14-5x", "t": "국제 라이선스 계약이나 기술도입 계약은 항상 신고 없이 자유롭게 체결할 수 있다.", "ox": "X", "c": "A", "tp": "국제 라이선스 신고"}, {"e": "IPAT 핵심", "i": "IPAT-4-14-6o", "t": "라이선스 계약의 분쟁 해결 조항은 중재, 조정, 법정 소송 등 양측이 합의한 방법으로 분쟁을 해결하게 한다.", "ox": "O", "c": "A", "tp": "분쟁 해결 조항"}, {"e": "IPAT 핵심", "i": "IPAT-4-14-6x", "t": "라이선스 계약의 분쟁 해결 조항은 반드시 법정 소송으로만 분쟁을 해결하도록 정한다.", "ox": "X", "c": "A", "tp": "분쟁 해결 조항"}, {"e": "IPAT 핵심", "i": "IPAT-4-14-7o", "t": "국제 라이선스 계약에서는 관할 법원, 적용 법률, 분쟁 해결 절차 등을 명확히 규정해 법적 불확실성을 줄인다.", "ox": "O", "c": "A", "tp": "국제 라이선스 계약의 내용"}], "15": [{"e": "IPAT 핵심", "i": "IPAT-4-15-1o", "t": "크로스 라이선스는 둘 이상의 기업이 각자의 지식재산권을 상대방에게 실시하도록 허여하는 방식으로, 경제적 가치가 동등하면 보통 무상으로 계약한다.", "ox": "O", "c": "A", "tp": "크로스 라이선스"}, {"e": "IPAT 핵심", "i": "IPAT-4-15-2o", "t": "크로스 라이선스에서 상호 허여하는 권리의 가치 차이가 있으면 해당 차액을 지불하고 사용하기도 한다.", "ox": "O", "c": "A", "tp": "크로스 라이선스의 차액 정산"}, {"e": "IPAT 핵심", "i": "IPAT-4-15-3o", "t": "크로스 라이선스를 체결하면 다른 기업과의 특허 소송에 드는 비용·인력·시간을 절약할 수 있어 글로벌 기업 간에 체결이 늘고 있다.", "ox": "O", "c": "A", "tp": "크로스 라이선스의 이점"}, {"e": "IPAT 핵심", "i": "IPAT-4-15-4o", "t": "Option Agreement는 최소한의 기술을 개시받은 뒤 일정한 검토기간이 지나 계약체결 여부를 결정하도록 하는 계약이다.", "ox": "O", "c": "A", "tp": "옵션 계약"}, {"e": "IPAT 핵심", "i": "IPAT-4-15-4x", "t": "Know-how Agreement는 최소한의 기술을 개시받은 뒤 일정한 검토기간이 지나 계약체결 여부를 결정하도록 하는 계약이다.", "ox": "X", "c": "A", "tp": "옵션 계약"}, {"e": "IPAT 핵심", "i": "IPAT-4-15-5o", "t": "Cross License Agreement는 실시권의 상호 허여에 관한 계약이고, Patent License Agreement는 특허의 실시권 허여 계약이다.", "ox": "O", "c": "A", "tp": "라이선스 관련 계약의 종류"}], "16": [{"e": "IPAT 핵심", "i": "IPAT-4-16-1o", "t": "라이선스 계약 절차의 1단계는 라이선서 입장에서 라이선싱 필요성과 사업화 전략 검토, 대상 선정, 지식재산 마케팅 등 기술 마케팅의 준비와 실시이다.", "ox": "O", "c": "A", "tp": "라이선싱 1단계"}, {"e": "IPAT 핵심", "i": "IPAT-4-16-1x", "t": "라이선스 계약 절차의 1단계는 라이선싱 조건의 협상 및 계약체결이다.", "ox": "X", "c": "A", "tp": "라이선싱 1단계"}, {"e": "IPAT 핵심", "i": "IPAT-4-16-2o", "t": "라이선싱을 위한 마케팅에서는 지식재산을 도면화·자료화·매뉴얼화해 유형화하고 테크노마트·전시회 같은 오프라인과 온라인 마케팅을 활용한다.", "ox": "O", "c": "A", "tp": "지식재산 마케팅"}, {"e": "IPAT 핵심", "i": "IPAT-4-16-2x", "t": "라이선싱을 위한 마케팅에서는 지식재산을 도면화·자료화·매뉴얼화하되 오프라인 마케팅은 활용하지 않는다.", "ox": "X", "c": "A", "tp": "지식재산 마케팅"}, {"e": "IPAT 핵심", "i": "IPAT-4-16-3o", "t": "라이선시를 선정할 때는 실시·사용 능력, 협력관계 지속을 위한 신뢰성, 사업영역과 전략에서의 상충 가능성 등을 고려한다.", "ox": "O", "c": "A", "tp": "잠재적 라이선시의 선정"}, {"e": "IPAT 핵심", "i": "IPAT-4-16-4o", "t": "라이선싱 2단계는 라이선시 발굴·선정 뒤 기술료 등 거래 조건을 협상하고 협상 결과를 계약서로 작성해 체결하는 단계이다.", "ox": "O", "c": "A", "tp": "2단계 조건 협상"}, {"e": "IPAT 핵심", "i": "IPAT-4-16-5o", "t": "기술료 결정에는 시장에서 적용되는 산출 방식과 요율을 이용하는 시장접근법과, 계약기간의 순이익을 기술 기여도에 따라 배분하는 순이익 배분 방식이 있다.", "ox": "O", "c": "A", "tp": "기술료 결정 방식"}, {"e": "IPAT 핵심", "i": "IPAT-4-16-5x", "t": "기술료 결정에는 비용접근법과 순이익 배분 방식만 있으며 시장접근법은 적용할 수 없다.", "ox": "X", "c": "A", "tp": "기술료 결정 방식"}, {"e": "IPAT 핵심", "i": "IPAT-4-16-6o", "t": "계약서는 기술제공 내용과 조건을 법적 구속력 있는 문서로 보존하고 계약 이행·해석의 기준이자 분쟁 해결의 기초 근거가 된다.", "ox": "O", "c": "A", "tp": "계약서의 역할"}, {"e": "IPAT 핵심", "i": "IPAT-4-16-7o", "t": "라이선싱 3단계는 필요한 신고·승인, 계약 실행, 기술료 수령 등 사후관리와 계약 완료로 이루어진다.", "ox": "O", "c": "A", "tp": "3단계 실행과 사후관리"}, {"e": "IPAT 핵심", "i": "IPAT-4-16-7x", "t": "라이선싱 3단계는 기술 마케팅의 준비와 실시로 구성된다.", "ox": "X", "c": "A", "tp": "3단계 실행과 사후관리"}, {"e": "IPAT 핵심", "i": "IPAT-4-16-8o", "t": "라이선서가 기술자료를 작성·송부할 경우 그 기술자료에 대한 비밀유지 의무를 라이선시에게 주지시켜야 한다.", "ox": "O", "c": "A", "tp": "기술자료의 비밀유지"}], "17": [{"e": "IPAT 핵심", "i": "IPAT-4-17-1o", "t": "라이선싱 기술료의 유형에는 정액 기술료, 마일스톤 기술료, 경상 기술료 등이 있고 한 계약에 둘 이상의 유형이 함께 포함될 수도 있다.", "ox": "O", "c": "A", "tp": "기술료 유형"}, {"e": "IPAT 핵심", "i": "IPAT-4-17-1x", "t": "라이선싱 기술료는 하나의 계약에 반드시 한 가지 유형만 정해야 하며 둘 이상의 유형을 함께 둘 수 없다.", "ox": "X", "c": "A", "tp": "기술료 유형"}, {"e": "IPAT 핵심", "i": "IPAT-4-17-2o", "t": "정액 기술료는 계약 시 한 번에 지불하는 고정 금액이며, 계약 체결 이후 특정 시점에 분납으로 나누어 받는 방식도 포함한다.", "ox": "O", "c": "A", "tp": "정액 기술료"}, {"e": "IPAT 핵심", "i": "IPAT-4-17-2x", "t": "정액 기술료는 라이선시가 제품을 판매할 때마다 지속적으로 지불하는 금액이다.", "ox": "X", "c": "A", "tp": "정액 기술료"}, {"e": "IPAT 핵심", "i": "IPAT-4-17-3o", "t": "마일스톤 기술료는 조건 달성부 기술료라고도 하며, 라이선시가 특정 개발 단계나 성과 조건을 달성할 때마다 지불한다.", "ox": "O", "c": "A", "tp": "마일스톤 기술료"}, {"e": "IPAT 핵심", "i": "IPAT-4-17-3x", "t": "마일스톤 기술료는 라이선시가 제품을 판매할 때마다 매출액의 일정 비율로 지속적으로 지불하는 기술료이다.", "ox": "X", "c": "A", "tp": "마일스톤 기술료"}, {"e": "IPAT 핵심", "i": "IPAT-4-17-4o", "t": "경상 기술료는 라이선스받은 기술로 만든 제품·서비스의 판매에 따라 지속적으로 지불하며 통상 총매출액의 일정 비율로 계산한다.", "ox": "O", "c": "A", "tp": "경상 기술료"}, {"e": "IPAT 핵심", "i": "IPAT-4-17-4x", "t": "경상 기술료는 계약 체결 시 한 번에 지불하는 고정 금액이며 이후 판매량과 무관하다.", "ox": "X", "c": "A", "tp": "경상 기술료"}, {"e": "IPAT 핵심", "i": "IPAT-4-17-5o", "t": "기타 기술료에는 기술이전 후 미실시에 대한 페널티로 지급하는 미실시 기술료와, 판매가 없어도 최저 금액을 내는 최저 기술료가 있다.", "ox": "O", "c": "A", "tp": "기타 기술료"}, {"e": "IPAT 핵심", "i": "IPAT-4-17-5x", "t": "최저 기술료는 기술이전 후 미실시에 따른 페널티로 지급하고, 미실시 기술료는 판매가 없어도 최저 금액을 내기로 하는 규정이다.", "ox": "X", "c": "A", "tp": "기타 기술료"}], "18": [{"e": "IPAT 핵심", "i": "IPAT-4-18-1o", "t": "장기 라이선스는 보통 선급금을 적게, 경상 실시료는 높게 설정하며, 라이선시가 스타트업이나 작은 기업일 때 양측에 유리할 수 있다.", "ox": "O", "c": "A", "tp": "장기 라이선스 기간"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-1x", "t": "장기 라이선스는 보통 선급금을 많이, 경상 실시료는 낮게 설정하는 방식이다.", "ox": "X", "c": "A", "tp": "장기 라이선스 기간"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-2o", "t": "장기 라이선스에서 라이선시가 사업을 포기하거나 재무적 어려움을 겪으면 라이선서 입장에서는 위험 부담이 있다.", "ox": "O", "c": "A", "tp": "장기 라이선스의 위험"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-2x", "t": "장기 라이선스에서 라이선시가 사업을 포기해도 라이선서 입장에서는 위험 부담이 없다.", "ox": "X", "c": "A", "tp": "장기 라이선스의 위험"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-3o", "t": "짧은 기간의 라이선스는 초기 선급금이 많고 경상 로열티는 상대적으로 적거나 아예 초기에 일시금으로 지급하는 방식이다.", "ox": "O", "c": "A", "tp": "단기 라이선스"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-3x", "t": "짧은 기간의 라이선스는 초기 선급금이 적고 경상 로열티를 높게 설정하는 방식이다.", "ox": "X", "c": "A", "tp": "단기 라이선스"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-4o", "t": "단기 라이선스는 과거 지식재산권을 침해한 라이선시에게 손해액을 배상받는 경우나 라이선시 재정이 불투명한 경우에 쓰일 수 있다.", "ox": "O", "c": "A", "tp": "단기 라이선스의 활용"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-5o", "t": "비독점 라이선스는 양 당사자의 위험을 줄일 수 있으며, 라이선서는 여러 사람에게 허여해 실시료 수입을 극대화하고 라이선시의 개량기술도 이익으로 얻는다.", "ox": "O", "c": "A", "tp": "비독점 라이선스의 장점"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-5x", "t": "비독점 라이선스를 허여하면 라이선서의 사업 성공 여부에 대한 리스크가 커진다.", "ox": "X", "c": "A", "tp": "비독점 라이선스의 장점"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-6o", "t": "독점 라이선스를 주면 그 범위 안에서 권리자도 실시할 수 없고 중첩되는 라이선스를 제3자에게 줄 수 없으므로, 라이선시의 시장점유율과 제조·판매능력을 면밀히 조사해야 한다.", "ox": "O", "c": "A", "tp": "독점 라이선스의 주의점"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-6x", "t": "독점 라이선스를 주더라도 권리자는 그 범위 안에서 계속 실시할 수 있고 제3자에게 중첩 라이선스도 줄 수 있다.", "ox": "X", "c": "A", "tp": "독점 라이선스의 주의점"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-7o", "t": "라이선스 계약의 개량기술 처리에 관한 합의는 보통 그랜트백(grant back) 조항으로 불리며, 라이선서는 라이선시가 개량한 기술에 일정한 권리를 갖는 쪽이 유리하다.", "ox": "O", "c": "A", "tp": "그랜트백 조항"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-7x", "t": "라이선스 계약의 개량기술 처리에 관한 합의는 보통 로열티백 조항으로 불리며 라이선시가 개량기술 권리를 갖는 쪽이 유리하다.", "ox": "X", "c": "A", "tp": "그랜트백 조항"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-8o", "t": "양 당사자는 개량기술을 서로 일정 조건으로 자유롭게 실시하게 하거나 공유하거나, 별도 라이선스를 체결할 의무 또는 협상 우선권을 주는 조항을 둘 수 있다.", "ox": "O", "c": "A", "tp": "개량기술의 처리"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-9o", "t": "핵심 라이선스 기술이 표준일 때는 개량기술이 표준에 통합되지 못하면 쓸모가 거의 없어, 라이선서가 라이선시의 개량기술에 대한 권리를 보유하는 것이 특히 중요하다.", "ox": "O", "c": "A", "tp": "라이선스 기술이 표준인 경우의 개량기술"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-10o", "t": "한국 법제에서 실시권자는 권리자의 동의 없이는 자신의 실시권을 양도하거나 재실시권을 설정할 수 없다.", "ox": "O", "c": "A", "tp": "실시권의 양도와 재실시권"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-10x", "t": "한국 법제에서 실시권자는 계약에 별도 정함이 없으면 자유롭게 자신의 실시권을 양도하거나 재실시권을 설정할 수 있다.", "ox": "X", "c": "A", "tp": "실시권의 양도와 재실시권"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-11o", "t": "재실시권 허락 권리를 라이선시에게 주는 경우에도 재실시권은 라이선서와 라이선시의 기존 계약 조건을 초과할 수 없다.", "ox": "O", "c": "A", "tp": "재실시권의 한도"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-12o", "t": "실시 수량에 최소 수량을 정하는 것은 라이선서 입장에서 최소한의 실시료를 확보하는 기능을 하므로 최저 실시료를 정하는 것과 같다.", "ox": "O", "c": "A", "tp": "실시 수량 제한"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-12x", "t": "실시 수량에 최대 수량을 정하는 것은 라이선서 입장에서 최소한의 실시료를 확보하는 기능을 하므로 최저 실시료를 정하는 것과 같다.", "ox": "X", "c": "A", "tp": "실시 수량 제한"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-13o", "t": "국내 시장은 직접 영위하고 해외 시장은 현지에서 경험 있는 회사에 라이선스하면 진입장벽과 현지 지식재산 보호 문제를 피할 수 있다.", "ox": "O", "c": "A", "tp": "해외 시장과 라이선싱"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-14o", "t": "실시 분야를 한정해 하나의 기술을 제품군별로 여러 라이선시와 계약하면 수익을 극대화할 수 있고, 생산이나 수입으로만 제한한 경우에도 판매를 포함하는 양도 권한은 준 것으로 해석된다.", "ox": "O", "c": "A", "tp": "실시 분야와 형태의 제한"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-14x", "t": "생산이나 수입으로만 실시 형태를 제한한 경우에는 판매를 포함하는 양도의 권한은 주지 않은 것으로 해석된다.", "ox": "X", "c": "A", "tp": "실시 분야와 형태의 제한"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-15o", "t": "대부분의 장기 라이선싱 거래는 라이선서 측의 실질적 기술지원을 필요로 하며, 상표 라이선스에서는 라이선시 제품의 품질관리를 위한 지원 업무가 요구된다.", "ox": "O", "c": "A", "tp": "기술지원"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-16o", "t": "라이선시가 제3자에게 재라이선싱(sublicensing)하는 경우 그 조건은 계약서에 명확히 명시하고, 재라이선싱 로열티의 배분과 관리책임을 분명히 적어야 한다.", "ox": "O", "c": "A", "tp": "재라이선싱"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-17o", "t": "주 라이선시(master licensee)는 라이선서에게 독점 라이선스를 받아 다시 다른 회사에 재라이선스하며, 부자재 개발과 기술마케팅 활동의 책임을 진다.", "ox": "O", "c": "A", "tp": "주 라이선시"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-18o", "t": "라이선싱 계약에는 통상 라이선서가 기술의 완전성을 담보하지 않는다는 내용이 포함되는데, 이는 물건의 하자담보책임이 판매자에게 있는 것과는 다른 IP의 특수성에서 비롯된다.", "ox": "O", "c": "A", "tp": "기술의 완전성 불담보"}, {"e": "IPAT 핵심", "i": "IPAT-4-18-19o", "t": "라이선시는 라이선싱 전에 대상 IP의 유효성(무효 가능성)을 면밀히 검토하고 이를 계약 대가에 반영할 필요가 있다.", "ox": "O", "c": "A", "tp": "특허의 유효성 검토"}], "19": [{"e": "IPAT 핵심", "i": "IPAT-4-19-1o", "t": "지식재산 가치평가에는 일반적으로 소득접근법, 비용접근법, 시장접근법이 쓰이며, 로열티공제법은 소득접근법과 시장접근법을 결합한 방법으로 지식재산 금융 평가에 널리 활용된다.", "ox": "O", "c": "A", "tp": "제2장 학습 개관"}, {"e": "IPAT 핵심", "i": "IPAT-4-19-1x", "t": "지식재산 가치평가에는 일반적으로 소득접근법, 비용접근법, 시장접근법이 쓰이며, 로열티공제법은 비용접근법과 시장접근법을 결합한 방법이다.", "ox": "X", "c": "A", "tp": "제2장 학습 개관"}, {"e": "IPAT 핵심", "i": "IPAT-4-19-2o", "t": "IP가치평가는 IP를 평가대상으로 하고 기술가치평가는 기술을 평가대상으로 한다는 점이 주된 차이이며, 두 평가는 원칙과 방법론이 상당 부분 유사하다.", "ox": "O", "c": "A", "tp": "IP가치평가와 기술가치평가의 대상"}, {"e": "IPAT 핵심", "i": "IPAT-4-19-2x", "t": "IP가치평가와 기술가치평가는 서로 전혀 다른 가치평가 원칙과 방법론을 적용한다.", "ox": "X", "c": "A", "tp": "IP가치평가와 기술가치평가의 대상"}, {"e": "IPAT 핵심", "i": "IPAT-4-19-3o", "t": "기술가치평가는 IP 없이 기술·노하우만 평가할 수도 있지만 IP가치평가에서는 IP 없이 기술·노하우만 평가하지 않는다.", "ox": "O", "c": "A", "tp": "IP 포함 여부"}, {"e": "IPAT 핵심", "i": "IPAT-4-19-3x", "t": "IP가치평가는 IP 없이 기술·노하우만 평가하는 경우도 있지만 기술가치평가는 반드시 IP를 포함한다.", "ox": "X", "c": "A", "tp": "IP 포함 여부"}, {"e": "IPAT 핵심", "i": "IPAT-4-19-4o", "t": "IP가치평가는 평가대상이 권리 자체이므로 IP에 중대한 권리 하자가 있으면 가치산정이 무의미할 수 있어, 권리성 분석의 역할이 기술가치평가보다 훨씬 중요하다.", "ox": "O", "c": "A", "tp": "권리성 분석의 역할"}, {"e": "IPAT 핵심", "i": "IPAT-4-19-4x", "t": "기술가치평가는 평가대상이 권리 자체이므로 권리성 분석의 역할이 IP가치평가보다 훨씬 중요하다.", "ox": "X", "c": "A", "tp": "권리성 분석의 역할"}, {"e": "IPAT 핵심", "i": "IPAT-4-19-5o", "t": "IP가치평가에서는 미래 현금흐름의 순현재가치에서 IP가 공헌한 상대적 비중인 IP기여도를 고려해야 한다.", "ox": "O", "c": "A", "tp": "IP기여도"}, {"e": "IPAT 핵심", "i": "IPAT-4-19-5x", "t": "IP가치평가에서는 IP기여도를 고려하지 않고 사업가치 전체를 IP의 가치로 본다.", "ox": "X", "c": "A", "tp": "IP기여도"}, {"e": "IPAT 핵심", "i": "IPAT-4-19-6o", "t": "지식재산 가치평가는 실무상 매출액이나 현금흐름을 전제할 수밖에 없어, 기술가치평가의 기본 원칙과 평가방법이 준용되되 지식재산권의 특수성을 고려해야 한다.", "ox": "O", "c": "A", "tp": "기술가치평가의 준용"}, {"e": "IPAT 핵심", "i": "IPAT-4-19-7o", "t": "기존 기술가치평가 모형은 기술과 지식재산권을 구분하지 않아 지식재산에 초점을 맞춘 평가에는 한계가 있다.", "ox": "O", "c": "A", "tp": "기술가치평가 모형의 한계"}], "20": [{"e": "IPAT 핵심", "i": "IPAT-4-20-1o", "t": "지식재산 거래의 가치평가 결과는 기업의 재무상태표에 적절히 반영되어야 한다.", "ox": "O", "c": "A", "tp": "평가 결과의 재무 반영"}, {"e": "IPAT 핵심", "i": "IPAT-4-20-1x", "t": "지식재산 거래의 가치평가 결과는 기업의 재무상태표에 반영하지 않아도 된다.", "ox": "X", "c": "A", "tp": "평가 결과의 재무 반영"}, {"e": "IPAT 핵심", "i": "IPAT-4-20-2o", "t": "지식재산의 이전·거래 활성화의 전제조건인 정확하고 신뢰도 있는 가치평가가 정착되지 못해 지식재산 거래가 정체되어 왔다.", "ox": "O", "c": "A", "tp": "가치평가 명문화 배경"}, {"e": "IPAT 핵심", "i": "IPAT-4-20-3o", "t": "지식재산 기본법에 따라 정부는 객관적 가치평가 촉진을 위해 지식재산 가치의 평가기법과 평가체계를 확립하고 이를 거래·금융 등에 활용하도록 지원해야 한다.", "ox": "O", "c": "A", "tp": "지식재산 기본법상 평가기법"}, {"e": "IPAT 핵심", "i": "IPAT-4-20-4o", "t": "발명진흥법 개정으로 지식재산 가치평가의 법적 근거가 명확해졌고, 특허청이 지정한 발명의 평가기관의 평가활동을 위한 자격제도 운영 가이드라인이 마련되었다.", "ox": "O", "c": "A", "tp": "발명진흥법과 평가기관"}, {"e": "IPAT 핵심", "i": "IPAT-4-20-4x", "t": "발명진흥법 개정으로 지식재산 가치평가의 법적 근거가 명확해졌고, 중소벤처기업부가 지정한 평가기관의 활동을 위한 가이드라인이 마련되었다.", "ox": "X", "c": "A", "tp": "발명진흥법과 평가기관"}, {"e": "IPAT 핵심", "i": "IPAT-4-20-5o", "t": "발명진흥법상 발명 등의 평가란 대상의 현재 또는 장래의 경제적 가치를 가액·등급 또는 점수 등으로 표시하는 것이다.", "ox": "O", "c": "A", "tp": "발명 등의 평가 정의"}, {"e": "IPAT 핵심", "i": "IPAT-4-20-6o", "t": "발명진흥법상 발명 등의 평가 기준은 대통령령으로 정하며, 평가기관은 평가 시 그 기준을 준수하여야 한다.", "ox": "O", "c": "A", "tp": "평가기준 준수"}, {"e": "IPAT 핵심", "i": "IPAT-4-20-6x", "t": "발명진흥법상 발명 등의 평가 기준은 특허청장이 임의로 정하며, 평가기관은 이를 참고할 수 있다.", "ox": "X", "c": "A", "tp": "평가기준 준수"}, {"e": "IPAT 핵심", "i": "IPAT-4-20-7o", "t": "개정 발명진흥법의 평가 대상인 발명 등에는 국내외에서 출원 중이거나 등록된 발명, 상표, 영업비밀, 배치설계가 포함된다.", "ox": "O", "c": "A", "tp": "발명 등의 평가 대상"}], "21": [{"e": "IPAT 핵심", "i": "IPAT-4-21-1o", "t": "지식재산 가치평가의 주요 용도에는 금융기관에 대한 담보, 매매·라이선스, 침해소송 손해배상액 산정, 현물출자 금액 산정, 직무발명 보상금액 결정 등이 있다.", "ox": "O", "c": "A", "tp": "지식재산 가치평가의 용도"}, {"e": "IPAT 핵심", "i": "IPAT-4-21-2o", "t": "지식재산 가치평가는 대상 지식재산의 권리범위를 확정해 그 범위 안의 기술을 대상 기술로 인식하며, 권리로 보호되지 않는 기술적 노하우는 구분한다.", "ox": "O", "c": "A", "tp": "권리범위 확정"}, {"e": "IPAT 핵심", "i": "IPAT-4-21-2x", "t": "지식재산 가치평가에서는 권리로 보호되지 않는 기술적 노하우도 대상 기술에 포함해 평가한다.", "ox": "X", "c": "A", "tp": "권리범위 확정"}, {"e": "IPAT 핵심", "i": "IPAT-4-21-3o", "t": "시장가치는 적절한 마케팅 기간이 주어진 뒤 이해관계가 없는 자발적 판매자와 구매자 사이에서 평가일 현재 자산이 교환될 추정 금액이다.", "ox": "O", "c": "A", "tp": "시장가치 원칙"}, {"e": "IPAT 핵심", "i": "IPAT-4-21-4o", "t": "평가조건을 설정할 때는 채택 가능성이 높은 조건을 설정해 가장 효율적이고 효과적인 사용(highest and best use) 원칙을 적용해야 한다.", "ox": "O", "c": "A", "tp": "최유효이용 원칙"}, {"e": "IPAT 핵심", "i": "IPAT-4-21-5o", "t": "평가 결과는 관점과 평가요인에 따라 달라질 수 있어 평가의 목적과 용도를 명시해야 하며, 이는 평가보고서의 분석내용과 평가금액이 유효하게 적용되는 범위를 결정한다.", "ox": "O", "c": "A", "tp": "평가 목적·용도의 명시"}, {"e": "IPAT 핵심", "i": "IPAT-4-21-6o", "t": "IP가치평가에서는 평가대상의 식별이 중요하며, 평가자는 원칙적으로 실태조사로 대상 IP기술을 확인하되 객관적이고 신뢰할 자료가 충분하면 실태조사를 생략할 수 있다.", "ox": "O", "c": "A", "tp": "평가대상의 식별과 실태조사"}, {"e": "IPAT 핵심", "i": "IPAT-4-21-6x", "t": "IP가치평가에서 평가자는 어떤 경우에도 실태조사를 생략할 수 없다.", "ox": "X", "c": "A", "tp": "평가대상의 식별과 실태조사"}], "22": [{"e": "IPAT 핵심", "i": "IPAT-4-22-1o", "t": "평가기관은 발명 등의 평가에서 기술성, 권리성, 시장성, 사업성 및 기타 평가요인을 분석해 가액·등급·점수 산정에 반영해야 한다.", "ox": "O", "c": "A", "tp": "주요 평가요인"}, {"e": "IPAT 핵심", "i": "IPAT-4-22-1x", "t": "평가기관은 발명 등의 평가에서 기술성과 권리성만 분석하고 시장성과 사업성은 분석하지 않는다.", "ox": "X", "c": "A", "tp": "주요 평가요인"}, {"e": "IPAT 핵심", "i": "IPAT-4-22-2o", "t": "기술성 분석은 대상 발명 등의 기술적 유용성과 경쟁력 수준을 분석하는 것으로 완성도·구현 가능성, 활용성·확장성, 비교우위·경쟁성 분석을 포함한다.", "ox": "O", "c": "A", "tp": "기술성 분석"}, {"e": "IPAT 핵심", "i": "IPAT-4-22-2x", "t": "기술성 분석은 대상 발명 등이 권리로서 적절히 보호되는지를 분석하는 것으로 선행기술과의 대비를 통한 권리 안정성 분석을 포함한다.", "ox": "X", "c": "A", "tp": "기술성 분석"}, {"e": "IPAT 핵심", "i": "IPAT-4-22-3o", "t": "권리성 분석은 대상 발명 등이 권리로서 적절히 보호되는지 분석하는 것으로 선행기술 대비 권리 안정성, 권리 보호강도, 제품·서비스 적용 여부 분석을 포함한다.", "ox": "O", "c": "A", "tp": "권리성 분석"}, {"e": "IPAT 핵심", "i": "IPAT-4-22-4o", "t": "시장성 분석은 시장환경과 시장경쟁 분석으로 적용제품이나 서비스의 시장경쟁력을 분석하는 것으로 시장규모·성장성, 시장 점유율 확보 가능성 분석을 포함한다.", "ox": "O", "c": "A", "tp": "시장성 분석"}, {"e": "IPAT 핵심", "i": "IPAT-4-22-4x", "t": "시장성 분석은 대상 발명 등을 활용한 사업의 경제성을 분석하는 것으로 사업화 주체의 마케팅 역량 분석을 포함한다.", "ox": "X", "c": "A", "tp": "시장성 분석"}, {"e": "IPAT 핵심", "i": "IPAT-4-22-5o", "t": "사업성 분석은 대상 발명 등을 활용한 사업의 경제성을 분석하는 것이며, 사업화 주체가 정해졌다면 그 주체의 개발·인적·마케팅 등 사업화 역량 분석도 포함한다.", "ox": "O", "c": "A", "tp": "사업성 분석"}, {"e": "IPAT 핵심", "i": "IPAT-4-22-5x", "t": "사업성 분석은 대상 발명 등이 적용되는 제품의 시장환경과 시장경쟁을 분석하는 것이다.", "ox": "X", "c": "A", "tp": "사업성 분석"}, {"e": "IPAT 핵심", "i": "IPAT-4-22-6o", "t": "지식재산 가치평가는 통상 금액으로 결정받아 왔으나, 최근 AI를 활용해 금액이 아닌 등급으로 가치를 평가하는 시스템도 등장했다.", "ox": "O", "c": "A", "tp": "가치평가의 형식"}, {"e": "IPAT 핵심", "i": "IPAT-4-22-6x", "t": "지식재산의 가치평가는 항상 금액으로만 결정하며 등급으로 평가하는 시스템은 없다.", "ox": "X", "c": "A", "tp": "가치평가의 형식"}], "23": [{"e": "IPAT 핵심", "i": "IPAT-4-23-1o", "t": "발명 등의 평가 방법은 일반적으로 시장접근법, 소득(수익)접근법, 비용(원가)접근법의 세 가지로 구분된다.", "ox": "O", "c": "A", "tp": "평가 방법의 3분류"}, {"e": "IPAT 핵심", "i": "IPAT-4-23-1x", "t": "발명 등의 평가 방법은 일반적으로 시장접근법, 소득접근법, 비교접근법으로 구분된다.", "ox": "X", "c": "A", "tp": "평가 방법의 3분류"}, {"e": "IPAT 핵심", "i": "IPAT-4-23-2o", "t": "시장접근법은 평가대상과 동일·유사한 지식재산이 활성 시장에서 거래된 가격에 근거해 상대적 가치를 산정하는 방법이다.", "ox": "O", "c": "A", "tp": "시장접근법"}, {"e": "IPAT 핵심", "i": "IPAT-4-23-2x", "t": "시장접근법은 평가대상 지식재산의 경제적 수명기간의 경제적 이익을 추정해 할인율로 현재가치로 환산하는 방법이다.", "ox": "X", "c": "A", "tp": "시장접근법"}, {"e": "IPAT 핵심", "i": "IPAT-4-23-3o", "t": "소득(수익)접근법은 평가대상의 경제적 수명기간에 사업화로 발생할 경제적 이익을 추정해 할인율로 현재가치로 환산하는 방법이다.", "ox": "O", "c": "A", "tp": "소득접근법"}, {"e": "IPAT 핵심", "i": "IPAT-4-23-4o", "t": "비용(원가)접근법은 대체의 경제 원리에 기초해 동일한 경제적 효익의 지식재산을 개발·구입하는 원가를 추정하는 방법으로, 기술개발비용·재생산원가·대체원가 정보가 필요하다.", "ox": "O", "c": "A", "tp": "비용접근법"}, {"e": "IPAT 핵심", "i": "IPAT-4-23-4x", "t": "비용(원가)접근법은 동일·유사 지식재산이 활성 시장에서 거래된 가격에 근거해 가치를 산정하는 방법이다.", "ox": "X", "c": "A", "tp": "비용접근법"}, {"e": "IPAT 핵심", "i": "IPAT-4-23-5o", "t": "시장접근법에는 거래사례비교법과 경매가 있고, 소득접근법에는 기술요소법, 다기간 초과이익법, 증분수익법, 잔여가치법, 실물옵션법이 있다.", "ox": "O", "c": "A", "tp": "접근법별 세부 방법"}, {"e": "IPAT 핵심", "i": "IPAT-4-23-5x", "t": "비용접근법에는 거래사례비교법과 경매가 있고, 시장접근법에는 역사적 비용, 재생산 비용, 대체 비용이 있다.", "ox": "X", "c": "A", "tp": "접근법별 세부 방법"}, {"e": "IPAT 핵심", "i": "IPAT-4-23-6o", "t": "접근법은 서로 다른 경제적 관점에 기반하므로 상이한 가치 결과를 낳을 수 있어 가치평가 제반 상황을 감안해 신중히 결정해야 한다.", "ox": "O", "c": "A", "tp": "평가 방법 간 결과 차이"}, {"e": "IPAT 핵심", "i": "IPAT-4-23-6x", "t": "접근법이 달라도 항상 동일한 가치 결과가 나오므로 어느 방법을 쓰든 무방하다.", "ox": "X", "c": "A", "tp": "평가 방법 간 결과 차이"}], "24": [{"e": "IPAT 핵심", "i": "IPAT-4-24-1o", "t": "로열티공제법(RFR)은 기업이 평가대상 IP를 보유하지 못해 제3자에게서 라이선스받는 경우를 가정해, 경제적 수명기간의 로열티의 현재가치를 기술가치로 추정하는 방법이다.", "ox": "O", "c": "A", "tp": "로열티공제법의 개념"}, {"e": "IPAT 핵심", "i": "IPAT-4-24-1x", "t": "로열티공제법은 평가대상 IP를 개발하는 데 든 원가를 추정해 가치를 산정하는 비용접근법에 속한다.", "ox": "X", "c": "A", "tp": "로열티공제법의 개념"}, {"e": "IPAT 핵심", "i": "IPAT-4-24-2o", "t": "로열티공제법은 기회비용 관점에서 평가대상 IP의 가치를 추정하는 접근법이며 평가대상 IP가 경제적 이익을 창출할 수 있다는 충분한 근거가 필요하다.", "ox": "O", "c": "A", "tp": "로열티공제법의 관점"}, {"e": "IPAT 핵심", "i": "IPAT-4-24-3o", "t": "로열티공제법은 로열티 수익 흐름을 현재가치로 환원하는 점에서 수익접근법으로, 기술시장의 로열티율 시장데이터를 쓰는 점에서 시장접근법으로 분류되기도 한다.", "ox": "O", "c": "A", "tp": "로열티공제법의 분류"}, {"e": "IPAT 핵심", "i": "IPAT-4-24-4o", "t": "로열티공제법에서는 대상 IP기술과 비교해 동일하거나 유사한 기술거래 로열티를 초기값으로 하고, 비교기술 간 속성 차이를 반영해 기본 로열티를 조정한다.", "ox": "O", "c": "A", "tp": "로열티공제법의 초기값"}, {"e": "IPAT 핵심", "i": "IPAT-4-24-5o", "t": "로열티공제법에서 로열티율은 추정 매출액에 곱해 로열티 수입을 추정하며, 세금을 제외한 세후 로열티 수입을 현재가치화해 연도별로 합하면 IP가치가 산출된다.", "ox": "O", "c": "A", "tp": "로열티 수입의 산출"}, {"e": "IPAT 핵심", "i": "IPAT-4-24-6o", "t": "로열티공제법의 투입 변수에는 시장규모와 예상매출액, IP의 경제적 수명, 로열티율, 현금흐름, 할인율이 있다.", "ox": "O", "c": "A", "tp": "로열티공제법 투입 변수"}, {"e": "IPAT 핵심", "i": "IPAT-4-24-7o", "t": "로열티공제법의 평가는 평가대상 IP 분석, 시장규모·매출액 예측, 경제적 수명 추정, 로열티율 추정, 잉여현금흐름 추정, 할인율 결정, 할인현금흐름 추정, 가치 산정, 최종 검토·조정 순으로 진행한다.", "ox": "O", "c": "A", "tp": "로열티공제법의 평가 순서"}], "25": [{"e": "IPAT 핵심", "i": "IPAT-4-25-1o", "t": "매출계획은 대상제품의 미래 수요예측이 선행되어야 하고 신제품은 관련 데이터가 없어 작성이 더 어려우므로, 관련 업계 종사자가 상식적으로 납득 가능한 수준에서 세워야 한다.", "ox": "O", "c": "A", "tp": "매출예측의 어려움"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-2o", "t": "매출예상액은 업계 평균 매출규모를 기본으로 하되, 사업지배계수가 높을수록 최대시장규모에 접근하는 것으로, 높지 않으면 업계 평균 매출액에 접근하는 것으로 설정한다.", "ox": "O", "c": "A", "tp": "사업지배계수"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-2x", "t": "매출예상액은 업계 평균 매출규모를 기본으로 하되, 사업지배계수가 낮을수록 최대시장규모에 접근하는 것으로 설정한다.", "ox": "X", "c": "A", "tp": "사업지배계수"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-3o", "t": "IP의 경제적 수명은 제품수명주기, 기술진보속도, 경쟁기술 출현가능성 등을 종합해 추정하며, 특허인용관계를 활용한 기술순환주기(TCT)를 참고자료로 쓰기도 한다.", "ox": "O", "c": "A", "tp": "경제적 수명 추정"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-4o", "t": "비교대상 IP의 로열티 사례가 없거나 매우 적으면 직접 산출하기보다 업종별 거래사례 로열티 통계에서 적정범위를 산출하고, 이것도 부족하면 상관행법 로열티 통계를 적용할 수 있다.", "ox": "O", "c": "A", "tp": "로열티율 산출 우선순위"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-5o", "t": "최종 로열티율은 기준 로열티율에 개별 IP의 기술적·권리적·시장적·사업적 특성을 포함한 조정계수를 반영하고, 전체 제품 중 평가대상 IP가 차지하는 비중까지 고려해 추정한다.", "ox": "O", "c": "A", "tp": "로열티율 결정 요소"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-6o", "t": "잉여현금흐름은 로열티 수익과 세금 비용 예측을 기준으로 현금유입과 현금유출의 차액을 연도별로 추정하며, 특허권의 경우 대상기간은 권리 잔존기간 이내에서 정한다.", "ox": "O", "c": "A", "tp": "잉여현금흐름 추정"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-6x", "t": "잉여현금흐름의 대상기간은 특허권의 경우 권리 잔존기간과 관계없이 사업의 매출이 지속되는 한 계속 잡는다.", "ox": "X", "c": "A", "tp": "잉여현금흐름 추정"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-7o", "t": "할인율은 특정 IP를 이용한 사업의 리스크를 반영하므로, 이미 사업화된 IP보다 사업성이 검증되지 않은 신기술 IP에서 리스크가 커 달리 적용해야 한다.", "ox": "O", "c": "A", "tp": "할인율 결정 요인"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-7x", "t": "할인율은 이미 사업화된 IP와 사업성이 검증되지 않은 신기술 IP에 동일하게 적용한다.", "ox": "X", "c": "A", "tp": "할인율 결정 요인"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-8o", "t": "상장기업의 자기자본 할인율은 무위험이자율에 시장수익률과 무위험이자율의 차이에 위험척도(β)를 곱한 값을 더해 산출한다.", "ox": "O", "c": "A", "tp": "자기자본 할인율"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-8x", "t": "상장기업의 자기자본 할인율은 시장수익률에 무위험이자율과 시장수익률의 차이에 위험척도(β)를 곱한 값을 더해 산출한다.", "ox": "X", "c": "A", "tp": "자기자본 할인율"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-9o", "t": "타인자본의 할인율은 지급이자의 비용인정에 따른 감세효과를 고려해 이자율×(1－법인세율)로 하고, 자기자본과 타인자본을 함께 쓰면 구성비로 가중평균해 가중평균 자본비용을 산출한다.", "ox": "O", "c": "A", "tp": "타인자본 할인율"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-9x", "t": "타인자본의 할인율은 조달금리를 감세효과 없이 그대로 적용한다.", "ox": "X", "c": "A", "tp": "타인자본 할인율"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-10o", "t": "할인현금흐름은 연도별 잉여현금흐름을 (1+할인율)의 연차 거듭제곱으로 나눈 값을 합산해 IP로 인한 사업가치를 구한다.", "ox": "O", "c": "A", "tp": "할인현금흐름"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-10x", "t": "할인현금흐름은 연도별 잉여현금흐름을 곱해 (1+할인율)의 거듭제곱을 합산하는 방식이다.", "ox": "X", "c": "A", "tp": "할인현금흐름"}, {"e": "IPAT 핵심", "i": "IPAT-4-25-11o", "t": "로열티공제법은 비교 가능한 동일·유사사례를 찾기 쉽지 않고, 자리를 잡은 기업의 매출 추정에 초점을 맞춰 기술기반 스타트업의 특허 평가에는 한계가 있다.", "ox": "O", "c": "A", "tp": "로열티공제법의 한계"}], "26": [{"e": "IPAT 핵심", "i": "IPAT-4-26-1o", "t": "소득접근법은 기업의 가치가 모든 자산의 수익획득 능력에 의존한다는 가정에서 출발해, IP를 활용한 사업의 미래 기대수익을 예측하고 이를 현재가치화하며 가장 현실적이라는 장점이 있다.", "ox": "O", "c": "A", "tp": "소득접근법의 의의"}, {"e": "IPAT 핵심", "i": "IPAT-4-26-2o", "t": "소득접근법에서는 장래 현금흐름을 적절한 할인율로 나누어 현재가치를 산출하는 할인현금흐름(DCF)법이 기본적으로 적용된다.", "ox": "O", "c": "A", "tp": "할인현금흐름법"}, {"e": "IPAT 핵심", "i": "IPAT-4-26-3o", "t": "국내에서 DCF 기반 소득접근법의 실무 방법으로는 IP요소법이 주로 쓰이며, 사업가치를 추정한 뒤 IP기여도를 곱해 IP 가치를 평가한다.", "ox": "O", "c": "A", "tp": "IP요소법"}, {"e": "IPAT 핵심", "i": "IPAT-4-26-3x", "t": "국내에서 DCF 기반 소득접근법의 실무 방법으로는 거래사례비교법이 주로 쓰이며, 사업가치에 IP기여도를 곱해 IP 가치를 평가한다.", "ox": "X", "c": "A", "tp": "IP요소법"}, {"e": "IPAT 핵심", "i": "IPAT-4-26-4o", "t": "IP요소법은 현금흐름 추정기간, 연도별 잉여현금흐름, 할인율, IP기여도, 이용률 다섯 가지 변수를 추정해야 한다.", "ox": "O", "c": "A", "tp": "IP요소법의 변수"}, {"e": "IPAT 핵심", "i": "IPAT-4-26-4x", "t": "IP요소법은 현금흐름 추정기간, 연도별 잉여현금흐름, 할인율, IP기여도 네 가지 변수만 추정하면 된다.", "ox": "X", "c": "A", "tp": "IP요소법의 변수"}, {"e": "IPAT 핵심", "i": "IPAT-4-26-5o", "t": "이용률은 평가 IP로 인해 발생하는 사업제품에 관련된 복수의 기술구성요소 중 평가 IP가 보호하는 비중을 뜻한다.", "ox": "O", "c": "A", "tp": "이용률"}, {"e": "IPAT 핵심", "i": "IPAT-4-26-5x", "t": "이용률은 사업제품 전체 매출액 중 평가 IP 관련 제품의 매출 비중을 뜻한다.", "ox": "X", "c": "A", "tp": "이용률"}, {"e": "IPAT 핵심", "i": "IPAT-4-26-6o", "t": "IP요소법 평가 순서에서는 할인현금흐름으로 사업가치를 산정한 뒤 IP기여도를 결정하고, 이용률을 추정한 다음 IP 가치를 산정한다.", "ox": "O", "c": "A", "tp": "IP요소법의 평가 순서"}, {"e": "IPAT 핵심", "i": "IPAT-4-26-7o", "t": "소득접근법에서 손익계산서로 현금흐름을 추정할 때 감가상각비·지급이자·배당은 비용이지만 실제 현금유출이 없을 수 있어, 순이익에 감가상각비를 더해 실제 생성되는 현금총액을 계산한다.", "ox": "O", "c": "A", "tp": "IP요소법의 현금흐름 추정"}, {"e": "IPAT 핵심", "i": "IPAT-4-26-8o", "t": "할인현금흐름으로 얻은 사업가치는 사업가·투자자·채권자와 IP 제공자가 나누어야 할 총액이므로 평가액이 바로 나오지 않고 IP 기여분의 배분 문제가 남는다.", "ox": "O", "c": "A", "tp": "IP 가치의 배분"}, {"e": "IPAT 핵심", "i": "IPAT-4-26-9o", "t": "사업가치에서 IP 기여분을 추출하는 방법으로는 초과이익 배분방식, 순이익 배분방식, 결정수익 환원방식이 주로 사용된다.", "ox": "O", "c": "A", "tp": "IP 기여분 추출 방식"}, {"e": "IPAT 핵심", "i": "IPAT-4-26-10o", "t": "이용률은 제품을 구성하는 세부기술을 모두 나열해 각 비중을 분석한 뒤 평가 IP에 해당하는 세부기술을 체크해 산출하며, 비중은 원가, 소비자 구매 요인, 전문가의 정성적 평가 등이 될 수 있다.", "ox": "O", "c": "A", "tp": "이용률 산출"}, {"e": "IPAT 핵심", "i": "IPAT-4-26-11o", "t": "소득접근법은 제반요소가 객관적으로 결정된다면 이론적으로 가장 타당한 방법이지만, 많은 가정과 변수가 개입되어 산정 결과의 변동성이 크다는 한계가 있다.", "ox": "O", "c": "A", "tp": "소득접근법의 한계"}, {"e": "IPAT 핵심", "i": "IPAT-4-26-11x", "t": "소득접근법은 가정과 변수의 개입이 적어 산정 결과의 변동성이 작다는 장점이 있다.", "ox": "X", "c": "A", "tp": "소득접근법의 한계"}, {"e": "IPAT 핵심", "i": "IPAT-4-26-12o", "t": "소득접근법은 후속 연구개발 같은 연속적 투자와 단계별 수익을 평가에 포함하지 못하고, 연관 프로젝트의 보완성이나 경영의 유연성·전략적 옵션을 반영하기 어렵다.", "ox": "O", "c": "A", "tp": "소득접근법의 이론적 문제점"}], "27": [{"e": "IPAT 핵심", "i": "IPAT-4-27-1o", "t": "비용접근법은 기술 또는 지식재산을 개발하는 데 든 제반 개발비용을 기초로 경과기간의 가치증감분을 차감해 산정하는 방법이다.", "ox": "O", "c": "A", "tp": "비용접근법의 개념"}, {"e": "IPAT 핵심", "i": "IPAT-4-27-2o", "t": "비용접근법은 측정이 비교적 용이하다는 장점이 있지만 수익성에 근거하지 않아 미래의 수익창출능력을 반영하지 못해, 주로 소득접근법이나 시장접근법의 보완자료로 쓴다.", "ox": "O", "c": "A", "tp": "비용접근법의 장단점"}, {"e": "IPAT 핵심", "i": "IPAT-4-27-2x", "t": "비용접근법은 미래의 수익창출능력을 잘 반영하는 장점이 있어 주로 단독 평가방법으로 쓴다.", "ox": "X", "c": "A", "tp": "비용접근법의 장단점"}, {"e": "IPAT 핵심", "i": "IPAT-4-27-3o", "t": "시장접근법은 유사한 지식재산이 거래된 가격을 조사해 평가대상의 가치를 산정하며, 매매 사례가 없거나 비교 가능성이 없으면 적용할 수 없다.", "ox": "O", "c": "A", "tp": "시장접근법의 개념"}, {"e": "IPAT 핵심", "i": "IPAT-4-27-4o", "t": "시장접근법을 쓰려면 비교 가능한 지식재산의 활발한 거래시장, 과거 거래실적, 접근 가능한 거래정보, 당사자의 자유의사에 의한 거래라는 특성이 필요하다.", "ox": "O", "c": "A", "tp": "시장접근법의 전제조건"}, {"e": "IPAT 핵심", "i": "IPAT-4-27-4x", "t": "시장접근법은 비교 가능한 지식재산의 거래실적이 없더라도 거래 당사자의 의사만 있으면 적용할 수 있다.", "ox": "X", "c": "A", "tp": "시장접근법의 전제조건"}, {"e": "IPAT 핵심", "i": "IPAT-4-27-5o", "t": "시장접근법은 평가대상과 유사한 자산의 거래정보가 많을 때 최적의 방법이며 라이선스 조건이나 로열티 결정에 자주 이용된다.", "ox": "O", "c": "A", "tp": "시장접근법의 활용"}, {"e": "IPAT 핵심", "i": "IPAT-4-27-5x", "t": "시장접근법은 평가대상과 유사한 자산의 거래정보가 거의 없을 때 최적의 방법이다.", "ox": "X", "c": "A", "tp": "시장접근법의 활용"}], "28": [{"e": "IPAT 핵심", "i": "IPAT-4-28-1o", "t": "기업회계기준서는 특정 조건을 충족하는 경우에만 무형자산을 인식하도록 요구하며, 장부금액 측정 방법과 공시 사항을 정하고 있다.", "ox": "O", "c": "A", "tp": "무형자산 회계기준"}, {"e": "IPAT 핵심", "i": "IPAT-4-28-2o", "t": "기업회계기준서는 자산에서 발생하는 미래 경제적 효익이 기업에 유입될 가능성이 높고 자산의 원가를 신뢰성 있게 측정할 수 있는 경우에만 무형자산을 인식한다.", "ox": "O", "c": "A", "tp": "무형자산 인식요건"}, {"e": "IPAT 핵심", "i": "IPAT-4-28-2x", "t": "기업회계기준서는 자산의 원가를 신뢰성 있게 측정할 수 있으면 미래 경제적 효익의 유입 가능성과 관계없이 무형자산을 인식한다.", "ox": "X", "c": "A", "tp": "무형자산 인식요건"}, {"e": "IPAT 핵심", "i": "IPAT-4-28-3o", "t": "자산의 분리가능성은 그 자산을 임대·매각·교환·분배할 수 있는 것을 뜻하며, 분리가능하지 않아도 계약상 권리 등 다른 방법으로 식별할 수 있으면 식별가능하다.", "ox": "O", "c": "A", "tp": "식별가능성"}, {"e": "IPAT 핵심", "i": "IPAT-4-28-4o", "t": "무형자산의 정의에서 식별가능성을 요구하는 것은 영업권과 구별하기 위해서이며, 영업권은 개별적으로 식별해 인식할 수 없는 자산에서 발생하는 미래 경제적 효익을 나타낸다.", "ox": "O", "c": "A", "tp": "영업권과의 구별"}, {"e": "IPAT 핵심", "i": "IPAT-4-28-4x", "t": "무형자산의 정의에서 식별가능성을 요구하는 것은 유형자산과 구별하기 위해서이다.", "ox": "X", "c": "A", "tp": "영업권과의 구별"}, {"e": "IPAT 핵심", "i": "IPAT-4-28-5o", "t": "자원에 대한 통제는 지식재산으로부터 미래의 경제적 효익을 배타적으로 얻고 제3자의 접근을 제한할 수 있는 경우를 말하며, 이는 법적 권리에서 나오는 것이 일반적이다.", "ox": "O", "c": "A", "tp": "자원에 대한 통제"}, {"e": "IPAT 핵심", "i": "IPAT-4-28-6o", "t": "다른 방법으로도 미래 경제적 효익을 통제할 수 있으므로 권리의 법적 집행가능성은 통제의 필요조건이 아니다.", "ox": "O", "c": "A", "tp": "통제의 법적 집행가능성"}, {"e": "IPAT 핵심", "i": "IPAT-4-28-6x", "t": "권리의 법적 집행가능성은 통제를 인정받기 위한 필요조건이다.", "ox": "X", "c": "A", "tp": "통제의 법적 집행가능성"}, {"e": "IPAT 핵심", "i": "IPAT-4-28-7o", "t": "무형자산의 미래 경제적 효익은 제품의 매출이나 용역수익, 원가절감 또는 자산 사용에 따른 기타 효익의 형태로 발생하며, 자산으로 인식하려면 이를 객관적으로 측정할 수 있어야 한다.", "ox": "O", "c": "A", "tp": "미래의 경제적 효익"}], "29": [{"e": "IPAT 핵심", "i": "IPAT-4-29-1o", "t": "지식재산은 경제적 효익을 제공할 것으로 추정되는 기간에 체계적으로 상각해야 하며 그 기간은 20년을 초과해서는 안 된다.", "ox": "O", "c": "A", "tp": "지식재산의 상각 기간"}, {"e": "IPAT 핵심", "i": "IPAT-4-29-1x", "t": "지식재산은 경제적 효익을 제공할 것으로 추정되는 기간에 체계적으로 상각해야 하며 그 기간은 30년까지 가능하다.", "ox": "X", "c": "A", "tp": "지식재산의 상각 기간"}, {"e": "IPAT 핵심", "i": "IPAT-4-29-2o", "t": "지식재산의 상각은 비용으로 인정되어 당기순이익을 줄이고 납세금액을 줄어들게 만든다.", "ox": "O", "c": "A", "tp": "상각의 세무 효과"}, {"e": "IPAT 핵심", "i": "IPAT-4-29-3o", "t": "내용연수가 비한정인 무형자산은 상각하지 않고 회수가능액과 장부금액을 비교해 손상검사를 수행하며, 회수가능액을 초과하는 장부금액은 손상차손으로 인식한다.", "ox": "O", "c": "A", "tp": "비한정 내용연수와 손상검사"}, {"e": "IPAT 핵심", "i": "IPAT-4-29-3x", "t": "내용연수가 비한정인 무형자산도 20년에 걸쳐 정액법으로 상각해야 한다.", "ox": "X", "c": "A", "tp": "비한정 내용연수와 손상검사"}, {"e": "IPAT 핵심", "i": "IPAT-4-29-4o", "t": "상각은 자산이 사용 가능한 때부터 시작하고, 매각예정으로 분류되는 날과 재무상태표에서 제거되는 날 중 이른 날에 중지한다.", "ox": "O", "c": "A", "tp": "상각의 시작과 중지"}, {"e": "IPAT 핵심", "i": "IPAT-4-29-5o", "t": "무형자산의 상각방법에는 정액법, 체감잔액법, 생산량비례법이 있으며, 소비 형태를 신뢰성 있게 결정할 수 없는 경우에는 정액법을 사용한다.", "ox": "O", "c": "A", "tp": "상각방법"}, {"e": "IPAT 핵심", "i": "IPAT-4-29-5x", "t": "무형자산의 상각방법에는 정액법, 체감잔액법, 생산량비례법이 있으며, 소비 형태를 신뢰성 있게 결정할 수 없는 경우에는 생산량비례법을 사용한다.", "ox": "X", "c": "A", "tp": "상각방법"}, {"e": "IPAT 핵심", "i": "IPAT-4-29-6o", "t": "무형자산의 상각액은 일반적으로 당기손익으로 인식하지만, 미래 경제적 효익이 다른 자산의 생산에 소모되면 그 상각액은 다른 자산의 장부금액에 포함한다.", "ox": "O", "c": "A", "tp": "상각액의 인식"}, {"e": "IPAT 핵심", "i": "IPAT-4-29-7o", "t": "내용연수가 유한한 지식재산의 잔존가치는 내용연수 종료 시점에 제3자가 구입하기로 한 약정이 있거나 활성시장이 있어 잔존가치를 결정할 수 있고 존재 가능성이 높은 경우를 제외하고는 영(0)으로 본다.", "ox": "O", "c": "A", "tp": "잔존가치"}, {"e": "IPAT 핵심", "i": "IPAT-4-29-7x", "t": "내용연수가 유한한 지식재산의 잔존가치는 원칙적으로 취득원가의 10%로 본다.", "ox": "X", "c": "A", "tp": "잔존가치"}, {"e": "IPAT 핵심", "i": "IPAT-4-29-8o", "t": "잔존가치는 적어도 매 회계연도 말에 검토하며, 잔존가치의 변동은 회계추정의 변경으로 처리한다.", "ox": "O", "c": "A", "tp": "잔존가치의 검토"}, {"e": "IPAT 핵심", "i": "IPAT-4-29-9o", "t": "내용연수가 유한한 지식재산의 상각기간과 상각방법은 적어도 매 회계연도 말에 검토하며, 예상 내용연수나 소비 형태가 달라지면 변경하고 이는 회계추정의 변경으로 처리한다.", "ox": "O", "c": "A", "tp": "상각기간 검토"}, {"e": "IPAT 핵심", "i": "IPAT-4-29-9x", "t": "내용연수가 유한한 지식재산의 상각기간과 상각방법은 한번 정하면 변경할 수 없고 오류수정으로만 처리한다.", "ox": "X", "c": "A", "tp": "상각기간 검토"}], "30": [{"e": "IPAT 핵심", "i": "IPAT-4-30-1o", "t": "지식재산권 라이선스로 지불한 대가는 라이선시 기업이 비용으로 처리하고, 라이선스로 수취한 대가는 라이선스가 사업 목적 범위에 있으면 영업매출에 더해진다.", "ox": "O", "c": "A", "tp": "라이선스 대가의 처리"}, {"e": "IPAT 핵심", "i": "IPAT-4-30-2o", "t": "취득 시 자산계상한 지식재산을 취득금액보다 높게 양도하면 양도이익을, 취득금액보다 낮게 양도하면 양도손실을 계상한다.", "ox": "O", "c": "A", "tp": "양도 시 회계처리"}, {"e": "IPAT 핵심", "i": "IPAT-4-30-2x", "t": "취득 시 자산계상한 지식재산을 취득금액보다 높게 양도하면 양도손실을 계상한다.", "ox": "X", "c": "A", "tp": "양도 시 회계처리"}, {"e": "IPAT 핵심", "i": "IPAT-4-30-3o", "t": "개별 취득하는 무형자산의 원가는 구입 가격과 자산을 의도한 목적에 사용할 수 있도록 준비하는 데 직접 관련되는 원가로 구성된다.", "ox": "O", "c": "A", "tp": "개별 취득"}, {"e": "IPAT 핵심", "i": "IPAT-4-30-4o", "t": "사업결합으로 취득하는 지식재산의 취득원가는 취득일 공정가치로 하며, 피취득자가 사업결합 전에 인식했는지와 관계없이 영업권과 분리해 별도 자산으로 인식한다.", "ox": "O", "c": "A", "tp": "사업결합 취득"}, {"e": "IPAT 핵심", "i": "IPAT-4-30-4x", "t": "사업결합으로 취득하는 지식재산의 취득원가는 피취득자의 장부금액으로 한다.", "ox": "X", "c": "A", "tp": "사업결합 취득"}, {"e": "IPAT 핵심", "i": "IPAT-4-30-5o", "t": "피취득자가 진행 중인 연구·개발 프로젝트는 자산의 정의를 충족하고 분리 가능하거나 계약상·법적 권리에서 발생하면 무형자산의 정의를 충족한다.", "ox": "O", "c": "A", "tp": "피취득자 연구개발 프로젝트"}, {"e": "IPAT 핵심", "i": "IPAT-4-30-6o", "t": "자산교환으로 무형자산을 취득할 때 원가는 교환거래에 상업적 실질이 결여되었거나 두 자산의 공정가치를 신뢰성 있게 측정할 수 없는 경우를 제외하고 공정가치로 측정한다.", "ox": "O", "c": "A", "tp": "자산교환 취득"}, {"e": "IPAT 핵심", "i": "IPAT-4-30-6x", "t": "자산교환으로 무형자산을 취득할 때 원가는 항상 제공한 자산의 장부금액으로 측정한다.", "ox": "X", "c": "A", "tp": "자산교환 취득"}, {"e": "IPAT 핵심", "i": "IPAT-4-30-7o", "t": "내부적으로 창출한 무형자산은 미래 경제적 효익을 창출할 식별가능한 자산의 존재 시점을 파악하기 어렵고 원가를 신뢰성 있게 결정하기 어려워 인식 기준 충족 평가가 쉽지 않다.", "ox": "O", "c": "A", "tp": "내부 창출 무형자산"}, {"e": "IPAT 핵심", "i": "IPAT-4-30-8o", "t": "내부 프로젝트를 연구 단계와 개발 단계로 구분할 수 없는 경우 그 프로젝트에서 발생한 지출은 모두 연구 단계에서 발생한 것으로 본다.", "ox": "O", "c": "A", "tp": "연구·개발 단계 구분 불가"}, {"e": "IPAT 핵심", "i": "IPAT-4-30-8x", "t": "내부 프로젝트를 연구 단계와 개발 단계로 구분할 수 없는 경우 그 지출은 모두 개발 단계에서 발생한 것으로 본다.", "ox": "X", "c": "A", "tp": "연구·개발 단계 구분 불가"}], "31": [{"e": "IPAT 핵심", "i": "IPAT-4-31-1o", "t": "국제회계기준서상 공정가치는 측정일 시점에 시장 참여자 간 정상거래에서 자산을 매도로 수취하거나 부채를 이전으로 지급해야 할 금액(유출 가격)이다.", "ox": "O", "c": "A", "tp": "공정가치의 정의"}, {"e": "IPAT 핵심", "i": "IPAT-4-31-2o", "t": "원가모형에서는 최초 인식 후 무형자산의 장부금액을 원가에서 상각누계액과 손상차손누계액을 차감한 금액으로 한다.", "ox": "O", "c": "A", "tp": "원가모형"}, {"e": "IPAT 핵심", "i": "IPAT-4-31-2x", "t": "원가모형에서는 최초 인식 후 무형자산의 장부금액을 재평가일의 공정가치에서 상각누계액과 손상차손누계액을 차감한 금액으로 한다.", "ox": "X", "c": "A", "tp": "원가모형"}, {"e": "IPAT 핵심", "i": "IPAT-4-31-3o", "t": "재평가모형은 재평가일의 공정가치에서 이후의 상각누계액과 손상차손누계액을 차감한 금액을 장부금액으로 하며, 이때 공정가치는 활성시장을 기초로 측정한다.", "ox": "O", "c": "A", "tp": "재평가모형"}, {"e": "IPAT 핵심", "i": "IPAT-4-31-4o", "t": "특허권이나 상표처럼 성격상 독특한 지식재산은 활성시장이 존재할 수 없어 재평가모형 적용이 어렵다.", "ox": "O", "c": "A", "tp": "활성시장 부재"}, {"e": "IPAT 핵심", "i": "IPAT-4-31-5o", "t": "무형자산을 선택적으로 재평가하거나 서로 다른 기준일의 금액이 혼재되는 것을 막기 위해 같은 분류 내의 무형자산 항목들은 동시에 재평가한다.", "ox": "O", "c": "A", "tp": "같은 분류의 동시 재평가"}, {"e": "IPAT 핵심", "i": "IPAT-4-31-6o", "t": "재평가로 무형자산의 장부금액이 증가하면 증가액은 기타포괄손익으로 인식해 재평가잉여금으로 자본에 가산하되, 이전에 당기손익으로 인식한 재평가감소 해당액은 한도로 당기손익으로 인식한다.", "ox": "O", "c": "A", "tp": "재평가 증가액 처리"}, {"e": "IPAT 핵심", "i": "IPAT-4-31-6x", "t": "재평가로 무형자산의 장부금액이 증가하면 증가액은 전액 당기손익으로 인식한다.", "ox": "X", "c": "A", "tp": "재평가 증가액 처리"}, {"e": "IPAT 핵심", "i": "IPAT-4-31-7o", "t": "재평가로 장부금액이 감소하면 감소액은 당기손익으로 인식하되, 해당 자산의 재평가잉여금 잔액이 있으면 그 한도로 기타포괄손익에서 먼저 줄인다.", "ox": "O", "c": "A", "tp": "재평가 감소액 처리"}], "32": [{"e": "IPAT 핵심", "i": "IPAT-4-32-1o", "t": "기술기반 기업에서는 특허기술이 핵심 자산이므로, 전통적인 부동산 담보 평가에서 벗어나 기술 및 지식재산 중심의 평가에 기반한 지식재산 금융이 중요해지고 있다.", "ox": "O", "c": "A", "tp": "제3장 학습 개관"}, {"e": "IPAT 핵심", "i": "IPAT-4-32-2o", "t": "지식재산(IP) 금융은 지식재산의 창출·사업화·활용 과정에서 지식재산을 기반으로 투자, 융자, 보증 등의 자금을 공급하는 금융 활동이다.", "ox": "O", "c": "A", "tp": "지식재산 금융의 정의"}, {"e": "IPAT 핵심", "i": "IPAT-4-32-2x", "t": "지식재산(IP) 금융은 기술의 개발에서 사업화에 이르는 전 과정에 기술 및 기업에 기초해 자금 접근성을 높이는 활동으로, 기술금융과 같은 개념이다.", "ox": "X", "c": "A", "tp": "지식재산 금융의 정의"}, {"e": "IPAT 핵심", "i": "IPAT-4-32-3o", "t": "기술금융은 기술 개발에서 사업화까지 전 과정의 자금 접근성을 높이기 위해 기술과 기업에 기초해 금융 기능을 제공하는 활동이며, 지식재산 금융은 그 진화된 기업금융의 한 형태이다.", "ox": "O", "c": "A", "tp": "기술금융과의 관계"}, {"e": "IPAT 핵심", "i": "IPAT-4-32-4o", "t": "지식재산 금융은 지식재산 담보대출, 지식재산 보증, 지식재산 투자의 세 가지 유형으로 구분된다.", "ox": "O", "c": "A", "tp": "지식재산 금융의 유형"}, {"e": "IPAT 핵심", "i": "IPAT-4-32-4x", "t": "지식재산 금융은 지식재산 담보대출, 지식재산 보증, 지식재산 신탁의 세 가지로 구분된다.", "ox": "X", "c": "A", "tp": "지식재산 금융의 유형"}, {"e": "IPAT 핵심", "i": "IPAT-4-32-5o", "t": "지식재산 담보대출은 산업은행·기업은행 등 은행이, 지식재산 보증은 신용보증기금·기술보증기금·서울신용보증재단이, 지식재산 투자는 벤처캐피털 등 투자전문 금융회사가 제공한다.", "ox": "O", "c": "A", "tp": "유형별 제공 기관"}, {"e": "IPAT 핵심", "i": "IPAT-4-32-5x", "t": "지식재산 보증은 산업은행·기업은행 등 은행이, 지식재산 담보대출은 신용보증기금·기술보증기금·서울신용보증재단이 제공한다.", "ox": "X", "c": "A", "tp": "유형별 제공 기관"}, {"e": "IPAT 핵심", "i": "IPAT-4-32-6o", "t": "지식재산 금융은 지식재산 자체를 수익창출 수단으로 하는 창의자본형과 지식재산을 매개로 금융서비스를 제공하는 창의기업형으로 구분할 수 있다.", "ox": "O", "c": "A", "tp": "창의자본형과 창의기업형"}, {"e": "IPAT 핵심", "i": "IPAT-4-32-7o", "t": "IP투자는 IP 자체에 대한 투자(창의자본형)와 IP를 보유한 기업에 대한 투자(창의기업형)가 모두 가능하고, IP보증은 지식재산 보유기업의 신용을 고려한 창의기업형 금융이다.", "ox": "O", "c": "A", "tp": "IP 투자와 IP 보증의 성격"}, {"e": "IPAT 핵심", "i": "IPAT-4-32-7x", "t": "IP보증은 지식재산 자체를 기초로 하는 창의자본형 금융이고, IP투자는 기업에 대한 투자만 가능한 창의기업형 금융이다.", "ox": "X", "c": "A", "tp": "IP 투자와 IP 보증의 성격"}, {"e": "IPAT 핵심", "i": "IPAT-4-32-8o", "t": "IP담보는 원칙적으로 지식재산 자체를 기초로 하는 창의자본형 금융이어야 하나 일부 금융권은 기업의 재무건전성도 함께 고려하며, 점진적으로 창의자본형으로 가고 있다.", "ox": "O", "c": "A", "tp": "IP담보의 성격"}, {"e": "IPAT 핵심", "i": "IPAT-4-32-8x", "t": "IP담보는 현재 점진적으로 창의기업형으로 움직이고 있다.", "ox": "X", "c": "A", "tp": "IP담보의 성격"}], "33": [{"e": "IPAT 핵심", "i": "IPAT-4-33-1o", "t": "1997년부터 2001년까지 추진된 기술담보시범사업은 지식재산권 가치평가액의 80%를 대출하고 회수불가 시 은행 손실비용의 90%를 정부가 보전하는 사업이었으나 정부 재정 부담이 커서 종료되었다.", "ox": "O", "c": "A", "tp": "기술담보시범사업"}, {"e": "IPAT 핵심", "i": "IPAT-4-33-1x", "t": "1997년부터 2001년까지 추진된 기술담보시범사업은 지식재산권 가치평가액의 90%를 대출하고 회수불가 시 은행 손실비용의 80%를 정부가 보전하는 사업이었다.", "ox": "X", "c": "A", "tp": "기술담보시범사업"}, {"e": "IPAT 핵심", "i": "IPAT-4-33-2o", "t": "특허청은 2006년에 모태펀드 특허계정에 550억 원을 출자하면서 특허기술 사업화 등 정책적 투자대상에 투자하는 IP투자펀드를 조성했다.", "ox": "O", "c": "A", "tp": "특허청의 IP투자펀드"}, {"e": "IPAT 핵심", "i": "IPAT-4-33-2x", "t": "특허청은 2006년에 모태펀드 특허계정에 250억 원을 출자하면서 특허기술 사업화 등 정책적 투자대상에 투자하는 IP투자펀드를 조성했다.", "ox": "X", "c": "A", "tp": "특허청의 IP투자펀드"}, {"e": "IPAT 핵심", "i": "IPAT-4-33-3o", "t": "1996년부터 시행한 발명의 평가지원 사업을 기술보증기금과 연계해 IP보증 서비스를 시작했고, 2013년에는 신용보증기금과 협약해 특허기술가치평가 연계보증을 시행했다.", "ox": "O", "c": "A", "tp": "특허기술가치평가 연계보증"}, {"e": "IPAT 핵심", "i": "IPAT-4-33-4o", "t": "기술개발 이후 사업화 단계에서 금융 공급이 부족하면 생산·판매와 고용창출로 이어지지 않으며, 금융이 부동산·재무 중심에서 기술·지식재산 중심의 평가로 이동하고 있어 IP금융 활성화가 필요하다.", "ox": "O", "c": "A", "tp": "지식재산 금융의 필요성"}], "34": [{"e": "IPAT 핵심", "i": "IPAT-4-34-1o", "t": "지식재산 기본법과 기술의 이전 및 사업화 촉진에 관한 법률은 권리화되지 않은 정보·지식까지 포함하는 포괄적 개념으로 정의하지만, 동산·채권 등의 담보에 관한 법률은 권리화된 지식재산을 대상으로 한다.", "ox": "O", "c": "A", "tp": "지식재산 개념의 포괄성"}, {"e": "IPAT 핵심", "i": "IPAT-4-34-1x", "t": "동산·채권 등의 담보에 관한 법률은 권리화되지 않은 정보·지식까지 포함하는 포괄적 개념으로 지식재산을 정의한다.", "ox": "X", "c": "A", "tp": "지식재산 개념의 포괄성"}, {"e": "IPAT 핵심", "i": "IPAT-4-34-2o", "t": "지식재산 기본법은 지식재산을 인간의 창조적 활동이나 경험 등으로 창출·발견된 지식·정보·기술, 사상이나 감정의 표현, 영업·물건의 표시, 생물의 품종·유전자원, 그 밖에 재산적 가치가 실현될 수 있는 무형적인 것으로 정의한다.", "ox": "O", "c": "A", "tp": "지식재산 기본법의 지식재산 정의"}, {"e": "IPAT 핵심", "i": "IPAT-4-34-3o", "t": "지식재산 기본법상 신지식재산은 경제·사회·문화의 변화나 과학기술의 발전에 따라 새로운 분야에서 출현하는 지식재산이고, 지식재산권은 법령·조약 등에 따라 인정되거나 보호되는 지식재산에 관한 권리이다.", "ox": "O", "c": "A", "tp": "신지식재산과 지식재산권"}, {"e": "IPAT 핵심", "i": "IPAT-4-34-4o", "t": "동산·채권 등의 담보에 관한 법률상 지식재산권담보권은 담보약정에 따라 질권을 설정할 수 있는 지식재산권을 목적으로 해당 개별 법률에 따라 등록한 담보권이다.", "ox": "O", "c": "A", "tp": "지식재산권담보권"}, {"e": "IPAT 핵심", "i": "IPAT-4-34-5o", "t": "지식재산 기본법에 따라 정부는 지식재산의 이전·거래·사업화를 촉진하기 위해 창업 활성화, 수요자·공급자 연계, 가치 증대와 자본 조성, 유동화 제도 정비, 투자·융자·신탁·보증·보험 활성화 방안을 포함한 시책을 마련해야 한다.", "ox": "O", "c": "A", "tp": "지식재산 활용 촉진 시책"}, {"e": "IPAT 핵심", "i": "IPAT-4-34-6o", "t": "지식재산권자가 동일한 채권 담보를 위해 둘 이상의 지식재산권을 담보로 제공하는 경우 특허원부·저작권등록부 등 공적 장부에 담보권을 등록할 수 있으며, 담보 대상 권리는 등록부를 관장하는 기관이 동일해야 한다.", "ox": "O", "c": "A", "tp": "지식재산권담보권 등록"}, {"e": "IPAT 핵심", "i": "IPAT-4-34-6x", "t": "지식재산권담보권 등록 시 담보 대상이 되는 지식재산권은 등록부를 관장하는 기관이 서로 달라도 무방하다.", "ox": "X", "c": "A", "tp": "지식재산권담보권 등록"}, {"e": "IPAT 핵심", "i": "IPAT-4-34-7o", "t": "부동산 담보능력이 부족한 중소기업이 동산·채권 등으로 자금을 조달하도록 동산·채권 등의 담보에 관한 법률이 2010년 6월 제정되어 2012년 6월 시행되었고, 지식재산권 등 모든 자산에 담보권 설정이 가능해졌다.", "ox": "O", "c": "A", "tp": "동산·채권담보법의 제정"}], "35": [{"e": "IPAT 핵심", "i": "IPAT-4-35-1o", "t": "지식재산 금융은 기업의 R&D, 창업, 사업화, 성장, 성숙의 사이클에서 단계별로 IP보증, IP담보대출, IP투자 등 각 유형별 금융기관을 통해 중소·벤처기업에 제공된다.", "ox": "O", "c": "A", "tp": "IP금융의 단계별 제공"}, {"e": "IPAT 핵심", "i": "IPAT-4-35-2o", "t": "2014년 본격 도입된 기술신용대출은 재무정보 등 신용평가에 기술력 평가를 추가로 고려해 신용도 판단 예측의 정확성을 높이는 기술금융 방식으로, 기술신용평가기관(TCB)에 평가를 의뢰해 대출 여부를 결정한다.", "ox": "O", "c": "A", "tp": "기술신용대출"}, {"e": "IPAT 핵심", "i": "IPAT-4-35-3o", "t": "기술신용대출은 신용에 기반한 대출이어서, 기업이 보유한 자산으로서의 지식재산권을 담보로 융자받는 IP담보대출과는 의미가 다르다.", "ox": "O", "c": "A", "tp": "기술신용대출과 IP담보대출의 차이"}, {"e": "IPAT 핵심", "i": "IPAT-4-35-3x", "t": "기술신용대출은 기업이 보유한 지식재산권을 담보로 융자받는 IP담보대출과 같은 개념이다.", "ox": "X", "c": "A", "tp": "기술신용대출과 IP담보대출의 차이"}, {"e": "IPAT 핵심", "i": "IPAT-4-35-4o", "t": "IP담보대출은 사업화 이후 어느 정도 매출이 발생하는 기업이 보유한 지식재산권을 담보로 은행에서 융자받는 방식이며, 은행이 IP가치평가기관에 평가를 의뢰해 그 결과를 토대로 대출한다.", "ox": "O", "c": "A", "tp": "IP담보대출의 방식"}, {"e": "IPAT 핵심", "i": "IPAT-4-35-4x", "t": "IP담보대출은 보증기관이 발급한 보증서를 기반으로 은행이 대출하는 방식이다.", "ox": "X", "c": "A", "tp": "IP담보대출의 방식"}, {"e": "IPAT 핵심", "i": "IPAT-4-35-5o", "t": "IP담보대출을 실시하려면 은행과 신청기업 간에 근질권설정계약을 체결하고 이를 특허청 등록원부에 설정등록해야 한다.", "ox": "O", "c": "A", "tp": "근질권 설정등록"}, {"e": "IPAT 핵심", "i": "IPAT-4-35-6o", "t": "질권의 설정등록 시에는 유질계약을 등록원인으로 등록하고 채무기업의 처분승낙서를 첨부하며, 특약사항으로 처분승낙서 내용과 공동담보 목록을 포함한다.", "ox": "O", "c": "A", "tp": "질권 설정등록 시 첨부"}], "36": [{"e": "IPAT 핵심", "i": "IPAT-4-36-1o", "t": "IP담보대출은 채무불이행 시 담보IP 처분에 높은 전문성이 필요하고 국내 IP 거래시장이 활성화되지 않아 처분 가능성이 낮아, 금융권이 IP를 담보로 취급하기를 어려워한다.", "ox": "O", "c": "A", "tp": "IP담보대출의 어려움"}, {"e": "IPAT 핵심", "i": "IPAT-4-36-1x", "t": "IP담보대출은 국내 IP 거래시장이 활성화되어 있어 처분 가능성이 높아 금융권이 담보 취급을 선호한다.", "ox": "X", "c": "A", "tp": "IP담보대출의 어려움"}, {"e": "IPAT 핵심", "i": "IPAT-4-36-2o", "t": "과거 회수지원펀드는 모태펀드와 은행의 공동출자로 조성되어 채무불이행이 발생하면 매입 시점에 담보IP를 재평가해 매입하는 구조였으나, 채무불이행 이후 사후 평가로 지원 여부를 정하는 한계가 있었다.", "ox": "O", "c": "A", "tp": "회수지원펀드"}, {"e": "IPAT 핵심", "i": "IPAT-4-36-3o", "t": "정부와 금융기관이 공동으로 마련한 회수지원기구는 IP담보대출 취급 시점부터 회수지원 여부를 결정해 금융권의 적극적 IP담보대출 취급을 가능하게 했다.", "ox": "O", "c": "A", "tp": "정부·금융기관 공동 회수지원기구"}, {"e": "IPAT 핵심", "i": "IPAT-4-36-3x", "t": "정부와 금융기관이 공동으로 마련한 회수지원기구는 채무불이행 발생 이후에 평가를 거쳐 회수지원 여부를 결정한다.", "ox": "X", "c": "A", "tp": "정부·금융기관 공동 회수지원기구"}, {"e": "IPAT 핵심", "i": "IPAT-4-36-4o", "t": "IP담보대출 신규 대출액은 2017년 1,655억 원에서 2022년 9,156억 원으로 늘었고 취급은행은 국책·시중은행에서 주요 지방은행까지 확산되었다.", "ox": "O", "c": "A", "tp": "IP담보대출 취급 성과"}, {"e": "IPAT 핵심", "i": "IPAT-4-36-5o", "t": "IP담보대출 금리는 2~3% 내외가 다수로 평균 4~5%대인 신용대출 금리보다 낮고, 대출 기업의 77.7%가 신용등급 BB+ 이하의 저신용기업이다.", "ox": "O", "c": "A", "tp": "IP담보대출 금리와 대상"}, {"e": "IPAT 핵심", "i": "IPAT-4-36-5x", "t": "IP담보대출 금리는 평균 4~5%대인 신용대출 금리보다 높고, 대출 기업 대부분이 우량 신용등급 기업이다.", "ox": "X", "c": "A", "tp": "IP담보대출 금리와 대상"}], "37": [{"e": "IPAT 핵심", "i": "IPAT-4-37-1o", "t": "지식재산 보증은 주로 물적 담보가 부족한 초기기업을 대상으로 보증기관이 지식재산 평가를 근거로 보증서를 발급하고 은행이 이를 기반으로 대출하는 방식이며, 채무불이행 시 보증기관이 리스크를 부담하는 관주도 금융이다.", "ox": "O", "c": "A", "tp": "지식재산 보증의 방식"}, {"e": "IPAT 핵심", "i": "IPAT-4-37-1x", "t": "지식재산 보증은 은행이 지식재산권을 직접 담보로 잡고 보증기관은 리스크를 부담하지 않는 방식이다.", "ox": "X", "c": "A", "tp": "지식재산 보증의 방식"}, {"e": "IPAT 핵심", "i": "IPAT-4-37-2o", "t": "국내에서 지식재산 평가 기반 보증상품은 신용보증기금, 기술보증기금, 서울신용보증재단을 중심으로 운영되며, 지식재산 창출·거래·사업화·활용촉진 단계별로 상품이 설계되어 있다.", "ox": "O", "c": "A", "tp": "지식재산 보증 운영기관"}, {"e": "IPAT 핵심", "i": "IPAT-4-37-3o", "t": "신용보증기금과 서울신용보증재단의 IP 우대보증은 한국발명진흥회 특허평가분석시스템을 연계해 B등급 이상 특허를 보유한 기업에 보증하며, 기술보증기금의 IP패스트보증은 기술보증기금 특허평가시스템을 활용한다.", "ox": "O", "c": "A", "tp": "IP 우대보증 상품"}, {"e": "IPAT 핵심", "i": "IPAT-4-37-3x", "t": "신용보증기금의 IP 우대보증은 B등급 이하 특허를 보유한 기업에 보증하는 상품이다.", "ox": "X", "c": "A", "tp": "IP 우대보증 상품"}, {"e": "IPAT 핵심", "i": "IPAT-4-37-4o", "t": "지식재산 보증 규모는 2017년 4,930억 원에서 2022년 8,781억 원으로 점진적으로 늘었고, 보증비율 우대(90~100%)와 보증료 감면(0.2~0.5%p) 혜택이 주어진다.", "ox": "O", "c": "A", "tp": "IP보증 규모와 혜택"}]};
window.PAIRS=[{"n": 1, "s": 0.9, "o": {"i": "IPAT-4-1-2o", "t": "사업화 유형은 리스크와 수익이 함께 커지는 관계로, IP 매각이 가장 낮고 전략적 제휴, 라이선싱, 합작투자, 기업 매수를 거쳐 벤처 창업이 가장 높다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-1-2x", "t": "사업화 유형 중 벤처 창업은 리스크와 수익이 모두 가장 낮고 IP 매각은 모두 가장 높다.", "e": "IPAT 핵심"}}, {"n": 1, "s": 0.9, "o": {"i": "IPAT-4-1-4o", "t": "지식재산의 사업화를 위해 새로운 스타트업을 설립하는 경우 리스크와 잠재수익이 모두 가장 높다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-1-4x", "t": "지식재산의 사업화를 위해 새로운 스타트업을 설립하는 경우 리스크는 가장 높지만 잠재수익은 가장 낮다.", "e": "IPAT 핵심"}}, {"n": 1, "s": 0.9, "o": {"i": "IPAT-4-1-7o", "t": "기존 기업이나 사업부를 매수하면 대상이 이미 개발과 인적·물적 구조를 갖추고 있어 스타트업 창업보다 리스크가 낮고 사업화 기간이 단축되며 통제력을 유지할 수 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-1-7x", "t": "기존 기업이나 사업부를 매수하면 스타트업 창업보다 리스크가 높고 사업화 기간이 더 길어진다.", "e": "IPAT 핵심"}}, {"n": 1, "s": 0.9, "o": {"i": "IPAT-4-1-8o", "t": "기업 매수는 상당한 투자가 요구되어 잠재 수익이 감소하고, 기업문화 융합의 어려움과 원치 않는 자산·부채 인수 및 돌발채무의 부담이 따를 수 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-1-8x", "t": "기업 매수는 투자 부담이 작아 잠재 수익이 오히려 커지며 기업문화 융합의 어려움이 거의 없다.", "e": "IPAT 핵심"}}, {"n": 2, "s": 0.9, "o": {"i": "IPAT-4-2-2o", "t": "합작투자는 참여 기업의 보완적인 기술과 자원으로 리스크가 감소하지만, 리스크와 수익을 소유자 간에 나누므로 스타트업 설립이나 기업매수보다 수익은 낮아진다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-2-2x", "t": "합작투자는 리스크와 수익을 나누지 않고 한 기업이 독점하므로 스타트업 설립보다 수익이 높아진다.", "e": "IPAT 핵심"}}, {"n": 2, "s": 0.9, "o": {"i": "IPAT-4-2-5o", "t": "한 기업이 다른 기업이 개발한 제품을 시장에 판매하여 수익 일부를 얻는 것은 수직적 제휴이고, 특정 시장 공략을 위해 상대 기업의 전문화된 기술을 활용하는 것은 수평적 제휴이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-2-5x", "t": "한 기업이 다른 기업이 개발한 제품을 시장에 판매하여 수익 일부를 얻는 것은 수평적 제휴이고, 상대 기업의 전문 기술을 활용하는 것은 수직적 제휴이다.", "e": "IPAT 핵심"}}, {"n": 3, "s": 0.9, "o": {"i": "IPAT-4-3-1o", "t": "라이선싱은 기술 보유자 입장에서는 자사 지식재산을 다른 기업에 이용 허가하여 수익을 창출하는 방법이고, 기술 도입자 입장에서는 기술적 과제를 해결하고 사업적 비전을 향상시키는 수단이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-3-1x", "t": "라이선싱은 기술 보유자에게만 경제적 수익이 생기고 기술 도입자에게는 아무런 이익이 없는 방법이다.", "e": "IPAT 핵심"}}, {"n": 3, "s": 0.9, "o": {"i": "IPAT-4-3-2o", "t": "라이선싱은 앞서 설명한 사업화 유형들보다 리스크가 낮은데, 리스크 대부분이 제품 개발·제조·마케팅을 맡는 라이선시(기술도입자)에게 이전되기 때문이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-3-2x", "t": "라이선싱은 리스크 대부분이 라이선서(기술제공자)에게 남아 다른 사업화 유형보다 리스크가 높다.", "e": "IPAT 핵심"}}, {"n": 3, "s": 0.9, "o": {"i": "IPAT-4-3-5o", "t": "지식재산을 다른 기업에 바로 판매하는 것은 리스크가 가장 낮은 방법이지만 높은 리스크를 구매자에게 넘기는 것이므로 상대적으로 수익은 낮아진다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-3-5x", "t": "지식재산을 다른 기업에 바로 판매하는 것은 리스크와 수익이 모두 가장 높은 방법이다.", "e": "IPAT 핵심"}}, {"n": 4, "s": 0.9, "o": {"i": "IPAT-4-4-1o", "t": "기술창업은 혁신적인 기술이나 아이디어로 새 시장을 만들어 제품·서비스를 생산·판매하는 창업 형태로, 지식재산의 보호와 활용이 중요하다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-4-1x", "t": "기술창업은 노하우와 경험에 근거해 기존 시장에서 제품·서비스를 판매하는 창업 형태로, 지식재산의 역할은 크지 않다.", "e": "IPAT 핵심"}}, {"n": 4, "s": 0.9, "o": {"i": "IPAT-4-4-3o", "t": "기술창업에서는 특허로 기술 혁신을 지키고, 상표로 제품과 브랜드를 식별하며, 저작권으로 창작물을 보호하는 전략을 쓴다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-4-3x", "t": "기술창업에서는 특허로 브랜드를 식별하고, 상표로 기술 혁신을 보호하며, 저작권으로 창작물을 지키는 전략을 쓴다.", "e": "IPAT 핵심"}}, {"n": 4, "s": 0.9, "o": {"i": "IPAT-4-4-4o", "t": "기술창업은 일반창업보다 독점성과 경쟁력이 강한 반면 기술수명주기가 있어 오래 유지하기 어렵다는 특성이 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-4-4x", "t": "기술창업은 일반창업보다 독점성과 경쟁력이 강하고 기술수명주기가 없어 오래 유지하기 쉽다는 특성이 있다.", "e": "IPAT 핵심"}}, {"n": 4, "s": 0.9, "o": {"i": "IPAT-4-4-5o", "t": "지식기술창업의 범주에는 주로 IT융합 분야의 콘텐츠·소프트웨어, 제조업 융합 분야, 지식 기반 서비스업이 포함되고 생계형 창업은 제외하는 것이 일반적이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-4-5x", "t": "지식기술창업의 범주에는 주로 IT융합 분야의 콘텐츠·소프트웨어와 함께 생계형 창업과 전통 제조 분야 창업도 포함하는 것이 일반적이다.", "e": "IPAT 핵심"}}, {"n": 5, "s": 0.9, "o": {"i": "IPAT-4-5-1o", "t": "기술창업에서는 아이템 사업화를 가능하게 하는 핵심 기술인력을 확보하지 못하면 창업 자체가 불가능할 수 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-5-1x", "t": "기술창업에서는 아이템 사업화를 가능하게 하는 핵심 기술인력을 확보하지 못하더라도 외주 인력으로 창업 자체는 항상 가능하다.", "e": "IPAT 핵심"}}, {"n": 5, "s": 0.9, "o": {"i": "IPAT-4-5-2o", "t": "창업 초기에는 사업성 있는 아이템을 포착하고 기술을 사업화할 역량이 중요한데, 많은 기업이 이 역량 확보에 실패한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-5-2x", "t": "창업 초기에는 사업성 있는 아이템을 포착하는 역량보다 대규모 설비투자 능력이 가장 중요하다.", "e": "IPAT 핵심"}}, {"n": 5, "s": 0.9, "o": {"i": "IPAT-4-5-3o", "t": "기술창업 초기에는 매출이 적어 기술 수준과 성장성 같은 무형의 가치를 평가받아야 하지만 이를 위한 시스템이 취약하다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-5-3x", "t": "기술창업 초기에는 매출이 크게 발생하므로 유형 자산 위주의 평가 시스템만으로도 충분히 가치를 평가받을 수 있다.", "e": "IPAT 핵심"}}, {"n": 6, "s": 0.9, "o": {"i": "IPAT-4-6-2o", "t": "기술창업 기본 절차는 창업구상 단계, 창업계획 단계, 사업실행 단계의 순서로 이어진다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-6-2x", "t": "기술창업 기본 절차는 창업계획 단계, 창업구상 단계, 사업실행 단계의 순서로 이어진다.", "e": "IPAT 핵심"}}, {"n": 6, "s": 0.9, "o": {"i": "IPAT-4-6-3o", "t": "창업구상 단계는 구체적인 아이템을 정하기 전에 창업자의 역량을 점검하고 시장·기술 조사로 가장 적합한 아이템을 구상하는 단계이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-6-3x", "t": "창업구상 단계는 회사를 설립하고 공장을 짓는 등 선정된 창업 아이템의 사업화를 진행하는 단계이다.", "e": "IPAT 핵심"}}, {"n": 6, "s": 0.9, "o": {"i": "IPAT-4-6-4o", "t": "창업계획 단계는 사업 타당성 검토와 사전계획 수립으로 시행착오를 줄이고 사업계획서를 작성하는 단계이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-6-4x", "t": "사업실행 단계는 사업 타당성 검토와 사전계획 수립으로 시행착오를 줄이고 사업계획서를 작성하는 단계이다.", "e": "IPAT 핵심"}}, {"n": 7, "s": 0.9, "o": {"i": "IPAT-4-7-1o", "t": "창업보육센터(인큐베이터)는 초기 창업자에게 사무 공간, 멘토링, 자금 지원, 네트워킹 기회 등을 제공해 창업을 돕는다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-7-1x", "t": "창업보육센터(인큐베이터)는 이미 성숙기에 접어든 대기업에 사무 공간, 멘토링, 자금 지원, 네트워킹 기회를 제공한다.", "e": "IPAT 핵심"}}, {"n": 7, "s": 0.9, "o": {"i": "IPAT-4-7-2o", "t": "스핀오프 창업은 기존 기업이나 연구기관이 개발한 기술을 이전받아 독립 회사를 세우는 형태로 기술적 리스크가 상대적으로 낮다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-7-2x", "t": "스핀오프 창업은 기존 기업이나 연구기관이 개발한 기술을 이전받아 독립 회사를 세우는 형태로 기술적 리스크가 상대적으로 높다.", "e": "IPAT 핵심"}}, {"n": 7, "s": 0.9, "o": {"i": "IPAT-4-7-3o", "t": "기술지주회사는 대학이나 연구기관이 보유한 기술의 상용화를 위해 설립된 회사로 기술이전과 사업화를 전문적으로 지원한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-7-3x", "t": "기술지주회사는 창업자가 직접 설립하는 일반 제조회사로 기술이전과 사업화는 정부 기관이 전담 지원한다.", "e": "IPAT 핵심"}}, {"n": 7, "s": 0.9, "o": {"i": "IPAT-4-7-5o", "t": "기술창업에서는 스톡옵션제도로 인재를 영입하고, B2G 사업 확대를 위해 NET·NEP 인증제도를 활용하는 것도 전략이 될 수 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-7-5x", "t": "기술창업에서는 스톡옵션제도로 인재를 영입하고, B2C 사업 확대를 위해 NET·NEP 인증제도를 활용하는 것도 전략이 될 수 있다.", "e": "IPAT 핵심"}}, {"n": 8, "s": 0.9, "o": {"i": "IPAT-4-8-1o", "t": "창업의 성공적 수행에는 사람, 아이디어, 시장, 자본이라는 요소가 필요하며 이 요소들이 상호작용해 성공 여부를 좌우한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-8-1x", "t": "창업의 성공적 수행에는 사람, 아이디어, 시장, 정부 인증이라는 네 요소가 필요하다.", "e": "IPAT 핵심"}}, {"n": 8, "s": 0.9, "o": {"i": "IPAT-4-8-2o", "t": "동업자는 창업자와 함께 금전·현물·기술을 투자하고 사업부문별 역할을 맡아 그 과실을 분배받는 사람으로 창업자 다음으로 중요한 구성원이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-8-2x", "t": "창업기업의 팀원은 금전·현물·기술을 투자하고 사업 과실을 분배받는 사람으로 창업자 다음으로 중요한 구성원이다.", "e": "IPAT 핵심"}}, {"n": 8, "s": 0.9, "o": {"i": "IPAT-4-8-5o", "t": "자기자본은 조달된 자본 중 상환 의무가 없는 자본으로, 법인기업에서는 주주나 출자자가 투자한 금액을 말한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-8-5x", "t": "자기자본은 금융기관 차입 등으로 조달하는 자본으로 상환 의무가 있다.", "e": "IPAT 핵심"}}, {"n": 8, "s": 0.9, "o": {"i": "IPAT-4-8-6o", "t": "타인자본은 친인척·지인·금융기관 차입처럼 주주나 출자자 투자 이외에 타인으로부터 조달하는 자금으로 상환 의무가 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-8-6x", "t": "타인자본은 친인척·지인·금융기관에서 조달한 자금이지만 상환 의무가 없는 자본이다.", "e": "IPAT 핵심"}}, {"n": 8, "s": 0.9, "o": {"i": "IPAT-4-8-7o", "t": "기술창업의 초기 자본은 주로 엔젤 투자자, 벤처캐피털, 정부 지원 프로그램을 통해 조달하는 것이 일반적이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-8-7x", "t": "기술창업의 초기 자본은 주로 상장 후 공모 증자를 통해 조달하는 것이 일반적이다.", "e": "IPAT 핵심"}}, {"n": 9, "s": 0.9, "o": {"i": "IPAT-4-9-1o", "t": "전통적으로 M&A는 규모의 경제와 시장점유율 확대가 목적이었으나 최근에는 지식재산이 M&A의 주요 요인으로 작용하고 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-9-1x", "t": "전통적으로 M&A는 지식재산 확보가 주된 목적이었으나 최근에는 규모의 경제와 시장점유율 확대가 주요 요인으로 작용하고 있다.", "e": "IPAT 핵심"}}, {"n": 9, "s": 0.9, "o": {"i": "IPAT-4-9-2o", "t": "독점적 이익을 얻기 위한 M&A는 다른 기업의 지식재산을 획득해 독점적 기술·제품을 보유하고 경쟁사보다 우월한 위치를 차지하려는 동기이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-9-2x", "t": "독점적 이익을 얻기 위한 M&A는 원재료 공급부터 판매까지 장악해 협상·조정 비용을 줄이려는 동기이다.", "e": "IPAT 핵심"}}, {"n": 9, "s": 0.9, "o": {"i": "IPAT-4-9-3o", "t": "원재료 공급부터 판매까지 장악하는 수직적 합병은 협상·조정·커뮤니케이션 비용과 광고·포장 비용을 줄일 수 있어 효율적 통제를 위한 동기가 된다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-9-3x", "t": "서로 다른 산업의 기업을 합병하는 수평적 합병은 원재료 공급부터 판매까지 장악하여 비용을 줄이는 효율적 통제 동기이다.", "e": "IPAT 핵심"}}, {"n": 9, "s": 0.9, "o": {"i": "IPAT-4-9-4o", "t": "채산성이 없거나 성장률이 낮을 것으로 예상되는 지식재산을 매각하고 주력업종에 집중하려는 것이 수익성 확보를 위한 M&A 동기이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-9-4x", "t": "수익성 확보를 위한 M&A는 성장률이 높을 것으로 예상되는 핵심 지식재산을 매각하고 비주력 사업에 집중하려는 동기이다.", "e": "IPAT 핵심"}}, {"n": 9, "s": 0.9, "o": {"i": "IPAT-4-9-5o", "t": "M&A로 기업은 규모의 경제와 범위의 경제를 실현하고 기술과 자원의 시너지를 극대화해 효율성을 높일 수 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-9-5x", "t": "M&A로 기업은 초기의 수익 추구를 위한 단기적 머니게임을 극대화해 효율성을 높일 수 있다.", "e": "IPAT 핵심"}}, {"n": 9, "s": 0.9, "o": {"i": "IPAT-4-9-6o", "t": "M&A로 지리적 다변화와 새 고객층 확보를 이루고 여러 시장에 리스크를 분산해 안정적 성장을 꾀할 수 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-9-6x", "t": "M&A로 시장 다변화를 하면 특정 시장에 위험을 집중시켜 안정적 성장을 꾀할 수 있다.", "e": "IPAT 핵심"}}, {"n": 9, "s": 0.9, "o": {"i": "IPAT-4-9-9o", "t": "시장 내 경쟁자를 제거하거나 약화시키기 위해 M&A를 하면 시장점유율을 높이고 가격 책정 등에서 우위를 점할 수 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-9-9x", "t": "M&A로 경쟁자를 제거하면 시장점유율은 높일 수 있지만 가격 책정 면에서의 우위는 얻을 수 없다.", "e": "IPAT 핵심"}}, {"n": 10, "s": 0.9, "o": {"i": "IPAT-4-10-2o", "t": "M&A에서는 개별 지식재산보다 기업 전체의 가치를 평가하는 것이 합리적인데, M&A가 기업의 개별 이전이 아닌 포괄적 이전이기 때문이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-10-2x", "t": "M&A에서는 기업 전체의 가치보다 개별 지식재산의 가치를 평가하는 것이 합리적인데, M&A가 개별적 이전이기 때문이다.", "e": "IPAT 핵심"}}, {"n": 10, "s": 0.9, "o": {"i": "IPAT-4-10-3o", "t": "M&A 과정에서 매입 대상 기업이 소유하거나 사용하는 지식재산은 자산실사(due diligence)를 통해 조사해야 한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-10-3x", "t": "M&A 과정에서 매입 대상 기업이 소유한 지식재산은 자산실사 대신 매각 후 사후 검토로 조사한다.", "e": "IPAT 핵심"}}, {"n": 10, "s": 0.9, "o": {"i": "IPAT-4-10-5o", "t": "등록된 IP의 보호기간이 곧 만료될 가능성이 있으면 가치를 재평가하거나 만료를 기다려 실시하는 방안을 검토한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-10-5x", "t": "등록된 IP의 보호기간이 곧 만료될 가능성이 있으면 보호기간과 관계없이 원래 평가액 그대로 매입한다.", "e": "IPAT 핵심"}}, {"n": 11, "s": 0.9, "o": {"i": "IPAT-4-11-2o", "t": "성장 전략은 제품라인 개발이나 신규 시장 확장 같은 장기 문제와 관련되며, 향후 18개월에서 5년의 경쟁 상황에 초점을 둔다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-11-2x", "t": "성장 전략은 낮은 이윤 같은 당면 문제의 해결과 관련되며, 향후 12~18개월의 경쟁 상황에 초점을 둔다.", "e": "IPAT 핵심"}}, {"n": 11, "s": 0.9, "o": {"i": "IPAT-4-11-5o", "t": "유지 전략은 낮은 성장률이나 이윤 축소 같은 당면 문제를 해결하기 위해 12~18개월 정도 걸리는 방안을 제시하며 이윤 제고와 수입 증대를 목표로 한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-11-5x", "t": "유지 전략은 신규 시장 확장 같은 장기 문제를 해결하기 위해 18개월에서 5년 정도 걸리는 방안을 제시하며 이윤 제고와 수입 증대를 목표로 한다.", "e": "IPAT 핵심"}}, {"n": 11, "s": 0.9, "o": {"i": "IPAT-4-11-8o", "t": "처분 전략은 경영실적이 나쁘거나 비전이 없는 사업의 특허, 주력 사업과 관련성이 낮은 특허 등을 타사에 판매해 수익 기회를 만드는 전략이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-11-8x", "t": "처분 전략은 주력 사업과 관련성이 높은 핵심 특허를 타사에 판매해 수익 기회를 만드는 전략이다.", "e": "IPAT 핵심"}}, {"n": 12, "s": 0.9, "o": {"i": "IPAT-4-12-1o", "t": "IP 라이선싱은 지식재산권 소유자가 다른 개인이나 기업에 해당 권리를 사용할 수 있는 권한을 부여하는 계약이며, 권리 양도와는 다르다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-12-1x", "t": "IP 라이선싱은 지식재산권 소유권 자체를 다른 개인이나 기업에 넘기는 양도 계약이다.", "e": "IPAT 핵심"}}, {"n": 12, "s": 0.9, "o": {"i": "IPAT-4-12-2o", "t": "독점 라이선스는 특정 라이선시에게만 사용 권한을 주고 다른 누구에게도 같은 권한을 주지 않으며, 비독점 라이선스는 여러 라이선시에게 같은 지식재산 사용을 허용한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-12-2x", "t": "독점 라이선스는 여러 라이선시에게 같은 지식재산 사용을 허용하고, 비독점 라이선스는 특정 라이선시에게만 사용 권한을 준다.", "e": "IPAT 핵심"}}, {"n": 12, "s": 0.9, "o": {"i": "IPAT-4-12-4o", "t": "라이선스를 주는 자가 라이선서(licensor)이고 라이선스를 받는 자가 라이선시(licensee)이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-12-4x", "t": "라이선스를 주는 자가 라이선시(licensee)이고 라이선스를 받는 자가 라이선서(licensor)이다.", "e": "IPAT 핵심"}}, {"n": 12, "s": 0.9, "o": {"i": "IPAT-4-12-5o", "t": "라이선싱 아웃은 라이선스를 타인에게 주는 것이고, 라이선싱 인은 타인의 권리에 대해 라이선스를 도입하는 것이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-12-5x", "t": "라이선싱 인은 라이선스를 타인에게 주는 것이고, 라이선싱 아웃은 타인의 권리에 대해 라이선스를 도입하는 것이다.", "e": "IPAT 핵심"}}, {"n": 12, "s": 0.9, "o": {"i": "IPAT-4-12-6o", "t": "특허권의 전용실시권은 등록이 효력 발생요건이고, 통상실시권은 계약에 의한 합의만으로 효력이 발생한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-12-6x", "t": "특허권의 통상실시권은 등록이 효력 발생요건이고, 전용실시권은 계약에 의한 합의만으로 효력이 발생한다.", "e": "IPAT 핵심"}}, {"n": 12, "s": 0.9, "o": {"i": "IPAT-4-12-7o", "t": "전용실시권이 설정·등록되면 그 범위 안에서는 특허권자도 특허발명을 실시할 수 없고 전용실시권자가 실시할 권리를 독점한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-12-7x", "t": "전용실시권이 설정·등록되더라도 그 범위 안에서 특허권자는 특허발명을 계속 실시할 수 있다.", "e": "IPAT 핵심"}}, {"n": 12, "s": 0.9, "o": {"i": "IPAT-4-12-8o", "t": "계약에 의한 실시권은 사적 자치의 원칙에 따라 기간을 한정하거나 실시 지역, 실시 제품 또는 형태를 한정해 설정할 수 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-12-8x", "t": "계약에 의한 실시권은 기간·지역·제품 형태를 한정할 수 없고 전면 허락만 가능하다.", "e": "IPAT 핵심"}}, {"n": 12, "s": 0.9, "o": {"i": "IPAT-4-12-9o", "t": "양자 간 계약으로 체결되는 폐쇄형 라이선스는 라이선시만 권리를 쓸 수 있지만, 개방형 라이선스는 일정 조건 아래 공개되어 누구나 이용할 수 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-12-9x", "t": "양자 간 계약으로 체결되는 개방형 라이선스는 라이선시만 권리를 쓸 수 있지만, 폐쇄형 라이선스는 누구나 이용할 수 있다.", "e": "IPAT 핵심"}}, {"n": 12, "s": 0.9, "o": {"i": "IPAT-4-12-11o", "t": "묵시적 라이선스는 정당한 권한자가 특허제품을 정당하게 유통했을 때 구매자에게 권리자가 침해를 주장할 수 없게 되는 것으로, 권리 소진 법리에 따른다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-12-11x", "t": "묵시적 라이선스는 권리자의 의사에 기반한 계약으로 발생하며 권리 소진의 법리와는 무관하다.", "e": "IPAT 핵심"}}, {"n": 13, "s": 0.9, "o": {"i": "IPAT-4-13-2o", "t": "라이선시는 필요한 기술의 권리를 받아 제품 가치를 높이고, 해당 권리로 인한 분쟁 위험도 제거해 안정적으로 사업을 할 수 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-13-2x", "t": "라이선시는 라이선스를 받아도 해당 권리에서 비롯되는 분쟁 위험은 그대로 부담한다.", "e": "IPAT 핵심"}}, {"n": 13, "s": 0.9, "o": {"i": "IPAT-4-13-4o", "t": "라이선서는 라이선시의 영업을 통해 새 시장에 진입할 수 있고, 새 시장 진입에 따른 설비 투자 비용과 사업 불확실성은 라이선시가 부담하게 된다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-13-4x", "t": "라이선서는 라이선시의 영업을 통해 새 시장에 진입할 수 있고, 새 시장 진입에 따른 설비 투자 비용과 사업 불확실성은 라이선서가 부담하게 된다.", "e": "IPAT 핵심"}}, {"n": 13, "s": 0.9, "o": {"i": "IPAT-4-13-6o", "t": "라이선서는 라이선시와 공동 개발·마케팅으로 라이선스 대상 기술이 산업 표준이 되도록 노력할 수 있고 실질적 표준 기술이 되게 할 수도 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-13-6x", "t": "라이선서는 표준으로 선정되지 않는 한 라이선스 대상 기술이 실질적 표준이 되도록 할 수 없다.", "e": "IPAT 핵심"}}, {"n": 14, "s": 0.9, "o": {"i": "IPAT-4-14-1o", "t": "라이선싱 계약의 조건에는 사용 범위, 사용 기간, 지불 방식, 지식재산의 유지·보호에 관한 사항이 포함되며 양측의 협상으로 정한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-14-1x", "t": "라이선싱 계약의 조건은 법령으로 일률적으로 정해지며 양측의 협상 여지는 없다.", "e": "IPAT 핵심"}}, {"n": 14, "s": 0.9, "o": {"i": "IPAT-4-14-2o", "t": "라이선스 계약의 필수요소는 계약 당사자, 실시허락의 대상 기술, 실시권의 세 가지이며, 실시료는 법적 필수요소가 아니다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-14-2x", "t": "라이선스 계약의 필수요소는 계약 당사자, 대상 기술, 실시권, 실시료의 네 가지이며 무상 계약은 라이선스 계약이 아니다.", "e": "IPAT 핵심"}}, {"n": 14, "s": 0.9, "o": {"i": "IPAT-4-14-3o", "t": "라이선스 계약은 계약자유의 원칙에 따라 전용실시인지 통상실시인지를 가리지 않고 합의만으로 성립하며 제3자의 동의나 행정청의 허가·등록이 필요 없다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-14-3x", "t": "전용실시 라이선스 계약은 합의만으로는 성립하지 않으며 행정청의 허가가 있어야 비로소 성립한다.", "e": "IPAT 핵심"}}, {"n": 14, "s": 0.9, "o": {"i": "IPAT-4-14-4o", "t": "공유특허권자는 다른 공유자의 동의를 받지 않으면 제3자에게 실시권을 허락할 수 없다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-14-4x", "t": "공유특허권자는 다른 공유자의 동의 없이도 제3자에게 자유롭게 실시권을 허락할 수 있다.", "e": "IPAT 핵심"}}, {"n": 14, "s": 0.9, "o": {"i": "IPAT-4-14-5o", "t": "국제 라이선스 계약이나 기술도입 계약을 체결할 때는 주무관청이나 공정거래위원회에 소정 사항을 신고해야 하는 경우도 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-14-5x", "t": "국제 라이선스 계약이나 기술도입 계약은 항상 신고 없이 자유롭게 체결할 수 있다.", "e": "IPAT 핵심"}}, {"n": 14, "s": 0.9, "o": {"i": "IPAT-4-14-6o", "t": "라이선스 계약의 분쟁 해결 조항은 중재, 조정, 법정 소송 등 양측이 합의한 방법으로 분쟁을 해결하게 한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-14-6x", "t": "라이선스 계약의 분쟁 해결 조항은 반드시 법정 소송으로만 분쟁을 해결하도록 정한다.", "e": "IPAT 핵심"}}, {"n": 15, "s": 0.9, "o": {"i": "IPAT-4-15-4o", "t": "Option Agreement는 최소한의 기술을 개시받은 뒤 일정한 검토기간이 지나 계약체결 여부를 결정하도록 하는 계약이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-15-4x", "t": "Know-how Agreement는 최소한의 기술을 개시받은 뒤 일정한 검토기간이 지나 계약체결 여부를 결정하도록 하는 계약이다.", "e": "IPAT 핵심"}}, {"n": 16, "s": 0.9, "o": {"i": "IPAT-4-16-1o", "t": "라이선스 계약 절차의 1단계는 라이선서 입장에서 라이선싱 필요성과 사업화 전략 검토, 대상 선정, 지식재산 마케팅 등 기술 마케팅의 준비와 실시이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-16-1x", "t": "라이선스 계약 절차의 1단계는 라이선싱 조건의 협상 및 계약체결이다.", "e": "IPAT 핵심"}}, {"n": 16, "s": 0.9, "o": {"i": "IPAT-4-16-2o", "t": "라이선싱을 위한 마케팅에서는 지식재산을 도면화·자료화·매뉴얼화해 유형화하고 테크노마트·전시회 같은 오프라인과 온라인 마케팅을 활용한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-16-2x", "t": "라이선싱을 위한 마케팅에서는 지식재산을 도면화·자료화·매뉴얼화하되 오프라인 마케팅은 활용하지 않는다.", "e": "IPAT 핵심"}}, {"n": 16, "s": 0.9, "o": {"i": "IPAT-4-16-5o", "t": "기술료 결정에는 시장에서 적용되는 산출 방식과 요율을 이용하는 시장접근법과, 계약기간의 순이익을 기술 기여도에 따라 배분하는 순이익 배분 방식이 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-16-5x", "t": "기술료 결정에는 비용접근법과 순이익 배분 방식만 있으며 시장접근법은 적용할 수 없다.", "e": "IPAT 핵심"}}, {"n": 16, "s": 0.9, "o": {"i": "IPAT-4-16-7o", "t": "라이선싱 3단계는 필요한 신고·승인, 계약 실행, 기술료 수령 등 사후관리와 계약 완료로 이루어진다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-16-7x", "t": "라이선싱 3단계는 기술 마케팅의 준비와 실시로 구성된다.", "e": "IPAT 핵심"}}, {"n": 17, "s": 0.9, "o": {"i": "IPAT-4-17-1o", "t": "라이선싱 기술료의 유형에는 정액 기술료, 마일스톤 기술료, 경상 기술료 등이 있고 한 계약에 둘 이상의 유형이 함께 포함될 수도 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-17-1x", "t": "라이선싱 기술료는 하나의 계약에 반드시 한 가지 유형만 정해야 하며 둘 이상의 유형을 함께 둘 수 없다.", "e": "IPAT 핵심"}}, {"n": 17, "s": 0.9, "o": {"i": "IPAT-4-17-2o", "t": "정액 기술료는 계약 시 한 번에 지불하는 고정 금액이며, 계약 체결 이후 특정 시점에 분납으로 나누어 받는 방식도 포함한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-17-2x", "t": "정액 기술료는 라이선시가 제품을 판매할 때마다 지속적으로 지불하는 금액이다.", "e": "IPAT 핵심"}}, {"n": 17, "s": 0.9, "o": {"i": "IPAT-4-17-3o", "t": "마일스톤 기술료는 조건 달성부 기술료라고도 하며, 라이선시가 특정 개발 단계나 성과 조건을 달성할 때마다 지불한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-17-3x", "t": "마일스톤 기술료는 라이선시가 제품을 판매할 때마다 매출액의 일정 비율로 지속적으로 지불하는 기술료이다.", "e": "IPAT 핵심"}}, {"n": 17, "s": 0.9, "o": {"i": "IPAT-4-17-4o", "t": "경상 기술료는 라이선스받은 기술로 만든 제품·서비스의 판매에 따라 지속적으로 지불하며 통상 총매출액의 일정 비율로 계산한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-17-4x", "t": "경상 기술료는 계약 체결 시 한 번에 지불하는 고정 금액이며 이후 판매량과 무관하다.", "e": "IPAT 핵심"}}, {"n": 17, "s": 0.9, "o": {"i": "IPAT-4-17-5o", "t": "기타 기술료에는 기술이전 후 미실시에 대한 페널티로 지급하는 미실시 기술료와, 판매가 없어도 최저 금액을 내는 최저 기술료가 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-17-5x", "t": "최저 기술료는 기술이전 후 미실시에 따른 페널티로 지급하고, 미실시 기술료는 판매가 없어도 최저 금액을 내기로 하는 규정이다.", "e": "IPAT 핵심"}}, {"n": 18, "s": 0.9, "o": {"i": "IPAT-4-18-1o", "t": "장기 라이선스는 보통 선급금을 적게, 경상 실시료는 높게 설정하며, 라이선시가 스타트업이나 작은 기업일 때 양측에 유리할 수 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-18-1x", "t": "장기 라이선스는 보통 선급금을 많이, 경상 실시료는 낮게 설정하는 방식이다.", "e": "IPAT 핵심"}}, {"n": 18, "s": 0.9, "o": {"i": "IPAT-4-18-2o", "t": "장기 라이선스에서 라이선시가 사업을 포기하거나 재무적 어려움을 겪으면 라이선서 입장에서는 위험 부담이 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-18-2x", "t": "장기 라이선스에서 라이선시가 사업을 포기해도 라이선서 입장에서는 위험 부담이 없다.", "e": "IPAT 핵심"}}, {"n": 18, "s": 0.9, "o": {"i": "IPAT-4-18-3o", "t": "짧은 기간의 라이선스는 초기 선급금이 많고 경상 로열티는 상대적으로 적거나 아예 초기에 일시금으로 지급하는 방식이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-18-3x", "t": "짧은 기간의 라이선스는 초기 선급금이 적고 경상 로열티를 높게 설정하는 방식이다.", "e": "IPAT 핵심"}}, {"n": 18, "s": 0.9, "o": {"i": "IPAT-4-18-5o", "t": "비독점 라이선스는 양 당사자의 위험을 줄일 수 있으며, 라이선서는 여러 사람에게 허여해 실시료 수입을 극대화하고 라이선시의 개량기술도 이익으로 얻는다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-18-5x", "t": "비독점 라이선스를 허여하면 라이선서의 사업 성공 여부에 대한 리스크가 커진다.", "e": "IPAT 핵심"}}, {"n": 18, "s": 0.9, "o": {"i": "IPAT-4-18-6o", "t": "독점 라이선스를 주면 그 범위 안에서 권리자도 실시할 수 없고 중첩되는 라이선스를 제3자에게 줄 수 없으므로, 라이선시의 시장점유율과 제조·판매능력을 면밀히 조사해야 한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-18-6x", "t": "독점 라이선스를 주더라도 권리자는 그 범위 안에서 계속 실시할 수 있고 제3자에게 중첩 라이선스도 줄 수 있다.", "e": "IPAT 핵심"}}, {"n": 18, "s": 0.9, "o": {"i": "IPAT-4-18-7o", "t": "라이선스 계약의 개량기술 처리에 관한 합의는 보통 그랜트백(grant back) 조항으로 불리며, 라이선서는 라이선시가 개량한 기술에 일정한 권리를 갖는 쪽이 유리하다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-18-7x", "t": "라이선스 계약의 개량기술 처리에 관한 합의는 보통 로열티백 조항으로 불리며 라이선시가 개량기술 권리를 갖는 쪽이 유리하다.", "e": "IPAT 핵심"}}, {"n": 18, "s": 0.9, "o": {"i": "IPAT-4-18-10o", "t": "한국 법제에서 실시권자는 권리자의 동의 없이는 자신의 실시권을 양도하거나 재실시권을 설정할 수 없다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-18-10x", "t": "한국 법제에서 실시권자는 계약에 별도 정함이 없으면 자유롭게 자신의 실시권을 양도하거나 재실시권을 설정할 수 있다.", "e": "IPAT 핵심"}}, {"n": 18, "s": 0.9, "o": {"i": "IPAT-4-18-12o", "t": "실시 수량에 최소 수량을 정하는 것은 라이선서 입장에서 최소한의 실시료를 확보하는 기능을 하므로 최저 실시료를 정하는 것과 같다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-18-12x", "t": "실시 수량에 최대 수량을 정하는 것은 라이선서 입장에서 최소한의 실시료를 확보하는 기능을 하므로 최저 실시료를 정하는 것과 같다.", "e": "IPAT 핵심"}}, {"n": 18, "s": 0.9, "o": {"i": "IPAT-4-18-14o", "t": "실시 분야를 한정해 하나의 기술을 제품군별로 여러 라이선시와 계약하면 수익을 극대화할 수 있고, 생산이나 수입으로만 제한한 경우에도 판매를 포함하는 양도 권한은 준 것으로 해석된다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-18-14x", "t": "생산이나 수입으로만 실시 형태를 제한한 경우에는 판매를 포함하는 양도의 권한은 주지 않은 것으로 해석된다.", "e": "IPAT 핵심"}}, {"n": 19, "s": 0.9, "o": {"i": "IPAT-4-19-1o", "t": "지식재산 가치평가에는 일반적으로 소득접근법, 비용접근법, 시장접근법이 쓰이며, 로열티공제법은 소득접근법과 시장접근법을 결합한 방법으로 지식재산 금융 평가에 널리 활용된다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-19-1x", "t": "지식재산 가치평가에는 일반적으로 소득접근법, 비용접근법, 시장접근법이 쓰이며, 로열티공제법은 비용접근법과 시장접근법을 결합한 방법이다.", "e": "IPAT 핵심"}}, {"n": 19, "s": 0.9, "o": {"i": "IPAT-4-19-2o", "t": "IP가치평가는 IP를 평가대상으로 하고 기술가치평가는 기술을 평가대상으로 한다는 점이 주된 차이이며, 두 평가는 원칙과 방법론이 상당 부분 유사하다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-19-2x", "t": "IP가치평가와 기술가치평가는 서로 전혀 다른 가치평가 원칙과 방법론을 적용한다.", "e": "IPAT 핵심"}}, {"n": 19, "s": 0.9, "o": {"i": "IPAT-4-19-3o", "t": "기술가치평가는 IP 없이 기술·노하우만 평가할 수도 있지만 IP가치평가에서는 IP 없이 기술·노하우만 평가하지 않는다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-19-3x", "t": "IP가치평가는 IP 없이 기술·노하우만 평가하는 경우도 있지만 기술가치평가는 반드시 IP를 포함한다.", "e": "IPAT 핵심"}}, {"n": 19, "s": 0.9, "o": {"i": "IPAT-4-19-4o", "t": "IP가치평가는 평가대상이 권리 자체이므로 IP에 중대한 권리 하자가 있으면 가치산정이 무의미할 수 있어, 권리성 분석의 역할이 기술가치평가보다 훨씬 중요하다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-19-4x", "t": "기술가치평가는 평가대상이 권리 자체이므로 권리성 분석의 역할이 IP가치평가보다 훨씬 중요하다.", "e": "IPAT 핵심"}}, {"n": 19, "s": 0.9, "o": {"i": "IPAT-4-19-5o", "t": "IP가치평가에서는 미래 현금흐름의 순현재가치에서 IP가 공헌한 상대적 비중인 IP기여도를 고려해야 한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-19-5x", "t": "IP가치평가에서는 IP기여도를 고려하지 않고 사업가치 전체를 IP의 가치로 본다.", "e": "IPAT 핵심"}}, {"n": 20, "s": 0.9, "o": {"i": "IPAT-4-20-1o", "t": "지식재산 거래의 가치평가 결과는 기업의 재무상태표에 적절히 반영되어야 한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-20-1x", "t": "지식재산 거래의 가치평가 결과는 기업의 재무상태표에 반영하지 않아도 된다.", "e": "IPAT 핵심"}}, {"n": 20, "s": 0.9, "o": {"i": "IPAT-4-20-4o", "t": "발명진흥법 개정으로 지식재산 가치평가의 법적 근거가 명확해졌고, 특허청이 지정한 발명의 평가기관의 평가활동을 위한 자격제도 운영 가이드라인이 마련되었다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-20-4x", "t": "발명진흥법 개정으로 지식재산 가치평가의 법적 근거가 명확해졌고, 중소벤처기업부가 지정한 평가기관의 활동을 위한 가이드라인이 마련되었다.", "e": "IPAT 핵심"}}, {"n": 20, "s": 0.9, "o": {"i": "IPAT-4-20-6o", "t": "발명진흥법상 발명 등의 평가 기준은 대통령령으로 정하며, 평가기관은 평가 시 그 기준을 준수하여야 한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-20-6x", "t": "발명진흥법상 발명 등의 평가 기준은 특허청장이 임의로 정하며, 평가기관은 이를 참고할 수 있다.", "e": "IPAT 핵심"}}, {"n": 21, "s": 0.9, "o": {"i": "IPAT-4-21-2o", "t": "지식재산 가치평가는 대상 지식재산의 권리범위를 확정해 그 범위 안의 기술을 대상 기술로 인식하며, 권리로 보호되지 않는 기술적 노하우는 구분한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-21-2x", "t": "지식재산 가치평가에서는 권리로 보호되지 않는 기술적 노하우도 대상 기술에 포함해 평가한다.", "e": "IPAT 핵심"}}, {"n": 21, "s": 0.9, "o": {"i": "IPAT-4-21-6o", "t": "IP가치평가에서는 평가대상의 식별이 중요하며, 평가자는 원칙적으로 실태조사로 대상 IP기술을 확인하되 객관적이고 신뢰할 자료가 충분하면 실태조사를 생략할 수 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-21-6x", "t": "IP가치평가에서 평가자는 어떤 경우에도 실태조사를 생략할 수 없다.", "e": "IPAT 핵심"}}, {"n": 22, "s": 0.9, "o": {"i": "IPAT-4-22-1o", "t": "평가기관은 발명 등의 평가에서 기술성, 권리성, 시장성, 사업성 및 기타 평가요인을 분석해 가액·등급·점수 산정에 반영해야 한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-22-1x", "t": "평가기관은 발명 등의 평가에서 기술성과 권리성만 분석하고 시장성과 사업성은 분석하지 않는다.", "e": "IPAT 핵심"}}, {"n": 22, "s": 0.9, "o": {"i": "IPAT-4-22-2o", "t": "기술성 분석은 대상 발명 등의 기술적 유용성과 경쟁력 수준을 분석하는 것으로 완성도·구현 가능성, 활용성·확장성, 비교우위·경쟁성 분석을 포함한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-22-2x", "t": "기술성 분석은 대상 발명 등이 권리로서 적절히 보호되는지를 분석하는 것으로 선행기술과의 대비를 통한 권리 안정성 분석을 포함한다.", "e": "IPAT 핵심"}}, {"n": 22, "s": 0.9, "o": {"i": "IPAT-4-22-4o", "t": "시장성 분석은 시장환경과 시장경쟁 분석으로 적용제품이나 서비스의 시장경쟁력을 분석하는 것으로 시장규모·성장성, 시장 점유율 확보 가능성 분석을 포함한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-22-4x", "t": "시장성 분석은 대상 발명 등을 활용한 사업의 경제성을 분석하는 것으로 사업화 주체의 마케팅 역량 분석을 포함한다.", "e": "IPAT 핵심"}}, {"n": 22, "s": 0.9, "o": {"i": "IPAT-4-22-5o", "t": "사업성 분석은 대상 발명 등을 활용한 사업의 경제성을 분석하는 것이며, 사업화 주체가 정해졌다면 그 주체의 개발·인적·마케팅 등 사업화 역량 분석도 포함한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-22-5x", "t": "사업성 분석은 대상 발명 등이 적용되는 제품의 시장환경과 시장경쟁을 분석하는 것이다.", "e": "IPAT 핵심"}}, {"n": 22, "s": 0.9, "o": {"i": "IPAT-4-22-6o", "t": "지식재산 가치평가는 통상 금액으로 결정받아 왔으나, 최근 AI를 활용해 금액이 아닌 등급으로 가치를 평가하는 시스템도 등장했다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-22-6x", "t": "지식재산의 가치평가는 항상 금액으로만 결정하며 등급으로 평가하는 시스템은 없다.", "e": "IPAT 핵심"}}, {"n": 23, "s": 0.9, "o": {"i": "IPAT-4-23-1o", "t": "발명 등의 평가 방법은 일반적으로 시장접근법, 소득(수익)접근법, 비용(원가)접근법의 세 가지로 구분된다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-23-1x", "t": "발명 등의 평가 방법은 일반적으로 시장접근법, 소득접근법, 비교접근법으로 구분된다.", "e": "IPAT 핵심"}}, {"n": 23, "s": 0.9, "o": {"i": "IPAT-4-23-2o", "t": "시장접근법은 평가대상과 동일·유사한 지식재산이 활성 시장에서 거래된 가격에 근거해 상대적 가치를 산정하는 방법이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-23-2x", "t": "시장접근법은 평가대상 지식재산의 경제적 수명기간의 경제적 이익을 추정해 할인율로 현재가치로 환산하는 방법이다.", "e": "IPAT 핵심"}}, {"n": 23, "s": 0.9, "o": {"i": "IPAT-4-23-4o", "t": "비용(원가)접근법은 대체의 경제 원리에 기초해 동일한 경제적 효익의 지식재산을 개발·구입하는 원가를 추정하는 방법으로, 기술개발비용·재생산원가·대체원가 정보가 필요하다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-23-4x", "t": "비용(원가)접근법은 동일·유사 지식재산이 활성 시장에서 거래된 가격에 근거해 가치를 산정하는 방법이다.", "e": "IPAT 핵심"}}, {"n": 23, "s": 0.9, "o": {"i": "IPAT-4-23-5o", "t": "시장접근법에는 거래사례비교법과 경매가 있고, 소득접근법에는 기술요소법, 다기간 초과이익법, 증분수익법, 잔여가치법, 실물옵션법이 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-23-5x", "t": "비용접근법에는 거래사례비교법과 경매가 있고, 시장접근법에는 역사적 비용, 재생산 비용, 대체 비용이 있다.", "e": "IPAT 핵심"}}, {"n": 23, "s": 0.9, "o": {"i": "IPAT-4-23-6o", "t": "접근법은 서로 다른 경제적 관점에 기반하므로 상이한 가치 결과를 낳을 수 있어 가치평가 제반 상황을 감안해 신중히 결정해야 한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-23-6x", "t": "접근법이 달라도 항상 동일한 가치 결과가 나오므로 어느 방법을 쓰든 무방하다.", "e": "IPAT 핵심"}}, {"n": 24, "s": 0.9, "o": {"i": "IPAT-4-24-1o", "t": "로열티공제법(RFR)은 기업이 평가대상 IP를 보유하지 못해 제3자에게서 라이선스받는 경우를 가정해, 경제적 수명기간의 로열티의 현재가치를 기술가치로 추정하는 방법이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-24-1x", "t": "로열티공제법은 평가대상 IP를 개발하는 데 든 원가를 추정해 가치를 산정하는 비용접근법에 속한다.", "e": "IPAT 핵심"}}, {"n": 25, "s": 0.9, "o": {"i": "IPAT-4-25-2o", "t": "매출예상액은 업계 평균 매출규모를 기본으로 하되, 사업지배계수가 높을수록 최대시장규모에 접근하는 것으로, 높지 않으면 업계 평균 매출액에 접근하는 것으로 설정한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-25-2x", "t": "매출예상액은 업계 평균 매출규모를 기본으로 하되, 사업지배계수가 낮을수록 최대시장규모에 접근하는 것으로 설정한다.", "e": "IPAT 핵심"}}, {"n": 25, "s": 0.9, "o": {"i": "IPAT-4-25-6o", "t": "잉여현금흐름은 로열티 수익과 세금 비용 예측을 기준으로 현금유입과 현금유출의 차액을 연도별로 추정하며, 특허권의 경우 대상기간은 권리 잔존기간 이내에서 정한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-25-6x", "t": "잉여현금흐름의 대상기간은 특허권의 경우 권리 잔존기간과 관계없이 사업의 매출이 지속되는 한 계속 잡는다.", "e": "IPAT 핵심"}}, {"n": 25, "s": 0.9, "o": {"i": "IPAT-4-25-7o", "t": "할인율은 특정 IP를 이용한 사업의 리스크를 반영하므로, 이미 사업화된 IP보다 사업성이 검증되지 않은 신기술 IP에서 리스크가 커 달리 적용해야 한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-25-7x", "t": "할인율은 이미 사업화된 IP와 사업성이 검증되지 않은 신기술 IP에 동일하게 적용한다.", "e": "IPAT 핵심"}}, {"n": 25, "s": 0.9, "o": {"i": "IPAT-4-25-8o", "t": "상장기업의 자기자본 할인율은 무위험이자율에 시장수익률과 무위험이자율의 차이에 위험척도(β)를 곱한 값을 더해 산출한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-25-8x", "t": "상장기업의 자기자본 할인율은 시장수익률에 무위험이자율과 시장수익률의 차이에 위험척도(β)를 곱한 값을 더해 산출한다.", "e": "IPAT 핵심"}}, {"n": 25, "s": 0.9, "o": {"i": "IPAT-4-25-9o", "t": "타인자본의 할인율은 지급이자의 비용인정에 따른 감세효과를 고려해 이자율×(1－법인세율)로 하고, 자기자본과 타인자본을 함께 쓰면 구성비로 가중평균해 가중평균 자본비용을 산출한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-25-9x", "t": "타인자본의 할인율은 조달금리를 감세효과 없이 그대로 적용한다.", "e": "IPAT 핵심"}}, {"n": 25, "s": 0.9, "o": {"i": "IPAT-4-25-10o", "t": "할인현금흐름은 연도별 잉여현금흐름을 (1+할인율)의 연차 거듭제곱으로 나눈 값을 합산해 IP로 인한 사업가치를 구한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-25-10x", "t": "할인현금흐름은 연도별 잉여현금흐름을 곱해 (1+할인율)의 거듭제곱을 합산하는 방식이다.", "e": "IPAT 핵심"}}, {"n": 26, "s": 0.9, "o": {"i": "IPAT-4-26-3o", "t": "국내에서 DCF 기반 소득접근법의 실무 방법으로는 IP요소법이 주로 쓰이며, 사업가치를 추정한 뒤 IP기여도를 곱해 IP 가치를 평가한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-26-3x", "t": "국내에서 DCF 기반 소득접근법의 실무 방법으로는 거래사례비교법이 주로 쓰이며, 사업가치에 IP기여도를 곱해 IP 가치를 평가한다.", "e": "IPAT 핵심"}}, {"n": 26, "s": 0.9, "o": {"i": "IPAT-4-26-4o", "t": "IP요소법은 현금흐름 추정기간, 연도별 잉여현금흐름, 할인율, IP기여도, 이용률 다섯 가지 변수를 추정해야 한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-26-4x", "t": "IP요소법은 현금흐름 추정기간, 연도별 잉여현금흐름, 할인율, IP기여도 네 가지 변수만 추정하면 된다.", "e": "IPAT 핵심"}}, {"n": 26, "s": 0.9, "o": {"i": "IPAT-4-26-5o", "t": "이용률은 평가 IP로 인해 발생하는 사업제품에 관련된 복수의 기술구성요소 중 평가 IP가 보호하는 비중을 뜻한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-26-5x", "t": "이용률은 사업제품 전체 매출액 중 평가 IP 관련 제품의 매출 비중을 뜻한다.", "e": "IPAT 핵심"}}, {"n": 26, "s": 0.9, "o": {"i": "IPAT-4-26-11o", "t": "소득접근법은 제반요소가 객관적으로 결정된다면 이론적으로 가장 타당한 방법이지만, 많은 가정과 변수가 개입되어 산정 결과의 변동성이 크다는 한계가 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-26-11x", "t": "소득접근법은 가정과 변수의 개입이 적어 산정 결과의 변동성이 작다는 장점이 있다.", "e": "IPAT 핵심"}}, {"n": 27, "s": 0.9, "o": {"i": "IPAT-4-27-2o", "t": "비용접근법은 측정이 비교적 용이하다는 장점이 있지만 수익성에 근거하지 않아 미래의 수익창출능력을 반영하지 못해, 주로 소득접근법이나 시장접근법의 보완자료로 쓴다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-27-2x", "t": "비용접근법은 미래의 수익창출능력을 잘 반영하는 장점이 있어 주로 단독 평가방법으로 쓴다.", "e": "IPAT 핵심"}}, {"n": 27, "s": 0.9, "o": {"i": "IPAT-4-27-4o", "t": "시장접근법을 쓰려면 비교 가능한 지식재산의 활발한 거래시장, 과거 거래실적, 접근 가능한 거래정보, 당사자의 자유의사에 의한 거래라는 특성이 필요하다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-27-4x", "t": "시장접근법은 비교 가능한 지식재산의 거래실적이 없더라도 거래 당사자의 의사만 있으면 적용할 수 있다.", "e": "IPAT 핵심"}}, {"n": 27, "s": 0.9, "o": {"i": "IPAT-4-27-5o", "t": "시장접근법은 평가대상과 유사한 자산의 거래정보가 많을 때 최적의 방법이며 라이선스 조건이나 로열티 결정에 자주 이용된다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-27-5x", "t": "시장접근법은 평가대상과 유사한 자산의 거래정보가 거의 없을 때 최적의 방법이다.", "e": "IPAT 핵심"}}, {"n": 28, "s": 0.9, "o": {"i": "IPAT-4-28-2o", "t": "기업회계기준서는 자산에서 발생하는 미래 경제적 효익이 기업에 유입될 가능성이 높고 자산의 원가를 신뢰성 있게 측정할 수 있는 경우에만 무형자산을 인식한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-28-2x", "t": "기업회계기준서는 자산의 원가를 신뢰성 있게 측정할 수 있으면 미래 경제적 효익의 유입 가능성과 관계없이 무형자산을 인식한다.", "e": "IPAT 핵심"}}, {"n": 28, "s": 0.9, "o": {"i": "IPAT-4-28-4o", "t": "무형자산의 정의에서 식별가능성을 요구하는 것은 영업권과 구별하기 위해서이며, 영업권은 개별적으로 식별해 인식할 수 없는 자산에서 발생하는 미래 경제적 효익을 나타낸다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-28-4x", "t": "무형자산의 정의에서 식별가능성을 요구하는 것은 유형자산과 구별하기 위해서이다.", "e": "IPAT 핵심"}}, {"n": 28, "s": 0.9, "o": {"i": "IPAT-4-28-6o", "t": "다른 방법으로도 미래 경제적 효익을 통제할 수 있으므로 권리의 법적 집행가능성은 통제의 필요조건이 아니다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-28-6x", "t": "권리의 법적 집행가능성은 통제를 인정받기 위한 필요조건이다.", "e": "IPAT 핵심"}}, {"n": 29, "s": 0.9, "o": {"i": "IPAT-4-29-1o", "t": "지식재산은 경제적 효익을 제공할 것으로 추정되는 기간에 체계적으로 상각해야 하며 그 기간은 20년을 초과해서는 안 된다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-29-1x", "t": "지식재산은 경제적 효익을 제공할 것으로 추정되는 기간에 체계적으로 상각해야 하며 그 기간은 30년까지 가능하다.", "e": "IPAT 핵심"}}, {"n": 29, "s": 0.9, "o": {"i": "IPAT-4-29-3o", "t": "내용연수가 비한정인 무형자산은 상각하지 않고 회수가능액과 장부금액을 비교해 손상검사를 수행하며, 회수가능액을 초과하는 장부금액은 손상차손으로 인식한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-29-3x", "t": "내용연수가 비한정인 무형자산도 20년에 걸쳐 정액법으로 상각해야 한다.", "e": "IPAT 핵심"}}, {"n": 29, "s": 0.9, "o": {"i": "IPAT-4-29-5o", "t": "무형자산의 상각방법에는 정액법, 체감잔액법, 생산량비례법이 있으며, 소비 형태를 신뢰성 있게 결정할 수 없는 경우에는 정액법을 사용한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-29-5x", "t": "무형자산의 상각방법에는 정액법, 체감잔액법, 생산량비례법이 있으며, 소비 형태를 신뢰성 있게 결정할 수 없는 경우에는 생산량비례법을 사용한다.", "e": "IPAT 핵심"}}, {"n": 29, "s": 0.9, "o": {"i": "IPAT-4-29-7o", "t": "내용연수가 유한한 지식재산의 잔존가치는 내용연수 종료 시점에 제3자가 구입하기로 한 약정이 있거나 활성시장이 있어 잔존가치를 결정할 수 있고 존재 가능성이 높은 경우를 제외하고는 영(0)으로 본다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-29-7x", "t": "내용연수가 유한한 지식재산의 잔존가치는 원칙적으로 취득원가의 10%로 본다.", "e": "IPAT 핵심"}}, {"n": 29, "s": 0.9, "o": {"i": "IPAT-4-29-9o", "t": "내용연수가 유한한 지식재산의 상각기간과 상각방법은 적어도 매 회계연도 말에 검토하며, 예상 내용연수나 소비 형태가 달라지면 변경하고 이는 회계추정의 변경으로 처리한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-29-9x", "t": "내용연수가 유한한 지식재산의 상각기간과 상각방법은 한번 정하면 변경할 수 없고 오류수정으로만 처리한다.", "e": "IPAT 핵심"}}, {"n": 30, "s": 0.9, "o": {"i": "IPAT-4-30-2o", "t": "취득 시 자산계상한 지식재산을 취득금액보다 높게 양도하면 양도이익을, 취득금액보다 낮게 양도하면 양도손실을 계상한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-30-2x", "t": "취득 시 자산계상한 지식재산을 취득금액보다 높게 양도하면 양도손실을 계상한다.", "e": "IPAT 핵심"}}, {"n": 30, "s": 0.9, "o": {"i": "IPAT-4-30-4o", "t": "사업결합으로 취득하는 지식재산의 취득원가는 취득일 공정가치로 하며, 피취득자가 사업결합 전에 인식했는지와 관계없이 영업권과 분리해 별도 자산으로 인식한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-30-4x", "t": "사업결합으로 취득하는 지식재산의 취득원가는 피취득자의 장부금액으로 한다.", "e": "IPAT 핵심"}}, {"n": 30, "s": 0.9, "o": {"i": "IPAT-4-30-6o", "t": "자산교환으로 무형자산을 취득할 때 원가는 교환거래에 상업적 실질이 결여되었거나 두 자산의 공정가치를 신뢰성 있게 측정할 수 없는 경우를 제외하고 공정가치로 측정한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-30-6x", "t": "자산교환으로 무형자산을 취득할 때 원가는 항상 제공한 자산의 장부금액으로 측정한다.", "e": "IPAT 핵심"}}, {"n": 30, "s": 0.9, "o": {"i": "IPAT-4-30-8o", "t": "내부 프로젝트를 연구 단계와 개발 단계로 구분할 수 없는 경우 그 프로젝트에서 발생한 지출은 모두 연구 단계에서 발생한 것으로 본다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-30-8x", "t": "내부 프로젝트를 연구 단계와 개발 단계로 구분할 수 없는 경우 그 지출은 모두 개발 단계에서 발생한 것으로 본다.", "e": "IPAT 핵심"}}, {"n": 31, "s": 0.9, "o": {"i": "IPAT-4-31-2o", "t": "원가모형에서는 최초 인식 후 무형자산의 장부금액을 원가에서 상각누계액과 손상차손누계액을 차감한 금액으로 한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-31-2x", "t": "원가모형에서는 최초 인식 후 무형자산의 장부금액을 재평가일의 공정가치에서 상각누계액과 손상차손누계액을 차감한 금액으로 한다.", "e": "IPAT 핵심"}}, {"n": 31, "s": 0.9, "o": {"i": "IPAT-4-31-6o", "t": "재평가로 무형자산의 장부금액이 증가하면 증가액은 기타포괄손익으로 인식해 재평가잉여금으로 자본에 가산하되, 이전에 당기손익으로 인식한 재평가감소 해당액은 한도로 당기손익으로 인식한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-31-6x", "t": "재평가로 무형자산의 장부금액이 증가하면 증가액은 전액 당기손익으로 인식한다.", "e": "IPAT 핵심"}}, {"n": 32, "s": 0.9, "o": {"i": "IPAT-4-32-2o", "t": "지식재산(IP) 금융은 지식재산의 창출·사업화·활용 과정에서 지식재산을 기반으로 투자, 융자, 보증 등의 자금을 공급하는 금융 활동이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-32-2x", "t": "지식재산(IP) 금융은 기술의 개발에서 사업화에 이르는 전 과정에 기술 및 기업에 기초해 자금 접근성을 높이는 활동으로, 기술금융과 같은 개념이다.", "e": "IPAT 핵심"}}, {"n": 32, "s": 0.9, "o": {"i": "IPAT-4-32-4o", "t": "지식재산 금융은 지식재산 담보대출, 지식재산 보증, 지식재산 투자의 세 가지 유형으로 구분된다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-32-4x", "t": "지식재산 금융은 지식재산 담보대출, 지식재산 보증, 지식재산 신탁의 세 가지로 구분된다.", "e": "IPAT 핵심"}}, {"n": 32, "s": 0.9, "o": {"i": "IPAT-4-32-5o", "t": "지식재산 담보대출은 산업은행·기업은행 등 은행이, 지식재산 보증은 신용보증기금·기술보증기금·서울신용보증재단이, 지식재산 투자는 벤처캐피털 등 투자전문 금융회사가 제공한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-32-5x", "t": "지식재산 보증은 산업은행·기업은행 등 은행이, 지식재산 담보대출은 신용보증기금·기술보증기금·서울신용보증재단이 제공한다.", "e": "IPAT 핵심"}}, {"n": 32, "s": 0.9, "o": {"i": "IPAT-4-32-7o", "t": "IP투자는 IP 자체에 대한 투자(창의자본형)와 IP를 보유한 기업에 대한 투자(창의기업형)가 모두 가능하고, IP보증은 지식재산 보유기업의 신용을 고려한 창의기업형 금융이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-32-7x", "t": "IP보증은 지식재산 자체를 기초로 하는 창의자본형 금융이고, IP투자는 기업에 대한 투자만 가능한 창의기업형 금융이다.", "e": "IPAT 핵심"}}, {"n": 32, "s": 0.9, "o": {"i": "IPAT-4-32-8o", "t": "IP담보는 원칙적으로 지식재산 자체를 기초로 하는 창의자본형 금융이어야 하나 일부 금융권은 기업의 재무건전성도 함께 고려하며, 점진적으로 창의자본형으로 가고 있다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-32-8x", "t": "IP담보는 현재 점진적으로 창의기업형으로 움직이고 있다.", "e": "IPAT 핵심"}}, {"n": 33, "s": 0.9, "o": {"i": "IPAT-4-33-1o", "t": "1997년부터 2001년까지 추진된 기술담보시범사업은 지식재산권 가치평가액의 80%를 대출하고 회수불가 시 은행 손실비용의 90%를 정부가 보전하는 사업이었으나 정부 재정 부담이 커서 종료되었다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-33-1x", "t": "1997년부터 2001년까지 추진된 기술담보시범사업은 지식재산권 가치평가액의 90%를 대출하고 회수불가 시 은행 손실비용의 80%를 정부가 보전하는 사업이었다.", "e": "IPAT 핵심"}}, {"n": 33, "s": 0.9, "o": {"i": "IPAT-4-33-2o", "t": "특허청은 2006년에 모태펀드 특허계정에 550억 원을 출자하면서 특허기술 사업화 등 정책적 투자대상에 투자하는 IP투자펀드를 조성했다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-33-2x", "t": "특허청은 2006년에 모태펀드 특허계정에 250억 원을 출자하면서 특허기술 사업화 등 정책적 투자대상에 투자하는 IP투자펀드를 조성했다.", "e": "IPAT 핵심"}}, {"n": 34, "s": 0.9, "o": {"i": "IPAT-4-34-1o", "t": "지식재산 기본법과 기술의 이전 및 사업화 촉진에 관한 법률은 권리화되지 않은 정보·지식까지 포함하는 포괄적 개념으로 정의하지만, 동산·채권 등의 담보에 관한 법률은 권리화된 지식재산을 대상으로 한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-34-1x", "t": "동산·채권 등의 담보에 관한 법률은 권리화되지 않은 정보·지식까지 포함하는 포괄적 개념으로 지식재산을 정의한다.", "e": "IPAT 핵심"}}, {"n": 34, "s": 0.9, "o": {"i": "IPAT-4-34-6o", "t": "지식재산권자가 동일한 채권 담보를 위해 둘 이상의 지식재산권을 담보로 제공하는 경우 특허원부·저작권등록부 등 공적 장부에 담보권을 등록할 수 있으며, 담보 대상 권리는 등록부를 관장하는 기관이 동일해야 한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-34-6x", "t": "지식재산권담보권 등록 시 담보 대상이 되는 지식재산권은 등록부를 관장하는 기관이 서로 달라도 무방하다.", "e": "IPAT 핵심"}}, {"n": 35, "s": 0.9, "o": {"i": "IPAT-4-35-3o", "t": "기술신용대출은 신용에 기반한 대출이어서, 기업이 보유한 자산으로서의 지식재산권을 담보로 융자받는 IP담보대출과는 의미가 다르다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-35-3x", "t": "기술신용대출은 기업이 보유한 지식재산권을 담보로 융자받는 IP담보대출과 같은 개념이다.", "e": "IPAT 핵심"}}, {"n": 35, "s": 0.9, "o": {"i": "IPAT-4-35-4o", "t": "IP담보대출은 사업화 이후 어느 정도 매출이 발생하는 기업이 보유한 지식재산권을 담보로 은행에서 융자받는 방식이며, 은행이 IP가치평가기관에 평가를 의뢰해 그 결과를 토대로 대출한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-35-4x", "t": "IP담보대출은 보증기관이 발급한 보증서를 기반으로 은행이 대출하는 방식이다.", "e": "IPAT 핵심"}}, {"n": 36, "s": 0.9, "o": {"i": "IPAT-4-36-1o", "t": "IP담보대출은 채무불이행 시 담보IP 처분에 높은 전문성이 필요하고 국내 IP 거래시장이 활성화되지 않아 처분 가능성이 낮아, 금융권이 IP를 담보로 취급하기를 어려워한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-36-1x", "t": "IP담보대출은 국내 IP 거래시장이 활성화되어 있어 처분 가능성이 높아 금융권이 담보 취급을 선호한다.", "e": "IPAT 핵심"}}, {"n": 36, "s": 0.9, "o": {"i": "IPAT-4-36-3o", "t": "정부와 금융기관이 공동으로 마련한 회수지원기구는 IP담보대출 취급 시점부터 회수지원 여부를 결정해 금융권의 적극적 IP담보대출 취급을 가능하게 했다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-36-3x", "t": "정부와 금융기관이 공동으로 마련한 회수지원기구는 채무불이행 발생 이후에 평가를 거쳐 회수지원 여부를 결정한다.", "e": "IPAT 핵심"}}, {"n": 36, "s": 0.9, "o": {"i": "IPAT-4-36-5o", "t": "IP담보대출 금리는 2~3% 내외가 다수로 평균 4~5%대인 신용대출 금리보다 낮고, 대출 기업의 77.7%가 신용등급 BB+ 이하의 저신용기업이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-36-5x", "t": "IP담보대출 금리는 평균 4~5%대인 신용대출 금리보다 높고, 대출 기업 대부분이 우량 신용등급 기업이다.", "e": "IPAT 핵심"}}, {"n": 37, "s": 0.9, "o": {"i": "IPAT-4-37-1o", "t": "지식재산 보증은 주로 물적 담보가 부족한 초기기업을 대상으로 보증기관이 지식재산 평가를 근거로 보증서를 발급하고 은행이 이를 기반으로 대출하는 방식이며, 채무불이행 시 보증기관이 리스크를 부담하는 관주도 금융이다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-37-1x", "t": "지식재산 보증은 은행이 지식재산권을 직접 담보로 잡고 보증기관은 리스크를 부담하지 않는 방식이다.", "e": "IPAT 핵심"}}, {"n": 37, "s": 0.9, "o": {"i": "IPAT-4-37-3o", "t": "신용보증기금과 서울신용보증재단의 IP 우대보증은 한국발명진흥회 특허평가분석시스템을 연계해 B등급 이상 특허를 보유한 기업에 보증하며, 기술보증기금의 IP패스트보증은 기술보증기금 특허평가시스템을 활용한다.", "e": "IPAT 핵심"}, "x": {"i": "IPAT-4-37-3x", "t": "신용보증기금의 IP 우대보증은 B등급 이하 특허를 보유한 기업에 보증하는 상품이다.", "e": "IPAT 핵심"}}];
